        if (ztnew10 < tmelt) then
          zlcp = als/(acpd*(1.+adv*zqnew10))
        else
          zlcp = alv/(acpd*(1.+adv*zqnew10))
        endif
        zdqsdt = ra2*(tmelt-ra4)*zqsnl*zcor/((ztnew10-ra4)*(ztnew10-ra4))
        zrain = (zqnew10-zqsnl)/(1.+zlcp*zdqsdt)
        ztnew11 = ztnew10+zlcp*zrain
        zqnew11 = zqnew10-zrain
        zqsnl = rdbrv*ra1*exp(ra2*(ztnew11-tmelt)/(ztnew11-ra4))/(dp(jhor)*sigma(jlev))
        zqsnl = amin1(zqsnl,rdbrv)
        zcor = 1./(1.-(1./rdbrv-1.)*zqsnl)
        zqsnl = zqsnl*zcor
        zdqsdt = ra2*(tmelt-ra4)*zqsnl*zcor/((ztnew11-ra4)*(ztnew11-ra4))
        zrain = (zqnew11-zqsnl)/(1.+zlcp*zdqsdt)
        ztnew12 = ztnew11+zlcp*zrain
        if (ztnew12 > zte(jhor,jlev)) then
          itop(jhor) = jlev
          ztp(jhor) = ztnew12
          zqsa = rdbrv*ra1*exp(ra2*(zte(jhor,jlev)-tmelt)/(zte(jhor,jlev)-ra4))/(dp(jhor)*sigma(jlev))
          zqsa = amin1(zqsa,rdbrv)
          zqsa = zqsa/(1.-(1./rdbrv-1.)*zqsa)
          zdqdt(jhor,jlev) = amax1(zqsa-zqe(jhor,jlev),0.)
          zdtdt(jhor,jlev) = ztp(jhor)-zte(jhor,jlev)
          zpt(jhor) = zdtdt(jhor,jlev)*dsigma(jlev)*zacpe(jhor,jlev)+zpt(jhor)
          zpq(jhor) = zdqdt(jhor,jlev)*dsigma(jlev)*zale(jhor,jlev)+zpq(jhor)
          if (kbeta > 0) then
            zbeta(jhor) = amin1(1.,zqe(jhor,jlev)/zqsa)*dsigma(jlev)+zbeta(jhor)
            zpbeta(jhor) = zpbeta(jhor)+dsigma(jlev)
          endif
        endif
      endif
    endif
  end do
endif
read(unit=171,rec=1+subcl_ad(4,5)) zpq
read(unit=172,rec=1+subcl_ad(4,5)) zpt
read(unit=170,rec=1+subcl_ad(4,5)) zi
read(unit=173,rec=1+subcl_ad(4,5)) zdtdt
read(unit=174,rec=1+subcl_ad(4,5)) zdqdt
zi(:) = amax1(0.,zi(:))
read(unit=168,rec=1+subcl_ad(4,5)) zaq
read(unit=169,rec=1+subcl_ad(4,5)) zat
if (nshallow == 1) then
  where (itop(:) > 0)
    zptop(:) = dp(:)*sigma(itop(:))
  end where
  where (itop(:) > 0 .and. zptop(:) > pdeep)
    ishallow(:) = 1
  end where
  where (itop(:) > 0 .and. zi(:) <= 0.)
    ishallow(:) = 1
  end where
endif
do jlev = 1, nlev
  ideep(:) = 0
  where (ilift(:) >= jlev .and. itop(:) <= jlev .and. zi(:) > 0. .and. ishallow(:) == 0.)
    ideep(:) = 1
  end where
  where (ideep(:) > 0)
    dqdt(:,jlev) = zaq(:)*zdqdt(:,jlev)/deltsec2-dqt(:,jlev)
    dtdt(:,jlev) = zat(:)*zdtdt(:,jlev)/deltsec2+dtdt(:,jlev)
  end where
end do
if (nshallow == 1) then
  call mkshallow( zte,zqe,ishallow,ilift,itop,zdtdts,zdqdts )
endif
if (nmoment == 1) then
  zue(:,:) = du(:,1:nlev)+dudt(:,1:nlev)*deltsec2
  zve(:,:) = dv(:,1:nlev)+dvdt(:,1:nlev)*deltsec2
  zau(:) = 0.
  where (zpt(:)+zpq(:) > 0.)
    zau(:) = amin1(1.,zi(:)/(zpt(:)+zpq(:)))
  end where
  read(unit=163,rec=1+subcl_ad(4,5)) zsums
  read(unit=161,rec=1+subcl_ad(4,5)) zvp
  read(unit=162,rec=1+subcl_ad(4,5)) zup
  do jlev = nlev, 1, -1
    where (ilift(:) >= jlev .and. itop(:) <= jlev .and. zi(:) > 0. .and. ishallow(:) == 0)
      zdvdt_ad(:,jlev) = zdvdt_ad(:,jlev)+dvdt_ad(:,jlev)/deltsec2
      zdudt_ad(:,jlev) = zdudt_ad(:,jlev)+dudt_ad(:,jlev)/deltsec2
      zau_ad(:) = zau_ad(:)+zdvdt_ad(:,jlev)*(zvp(:)-zve(:,jlev))
      zve_ad(:,jlev) = zve_ad(:,jlev)-zdvdt_ad(:,jlev)*zau(:)
      zvp_ad(:) = zvp_ad(:)+zdvdt_ad(:,jlev)*zau(:)
      zdvdt_ad(:,jlev) = 0.
      zau_ad(:) = zau_ad(:)+zdudt_ad(:,jlev)*(zup(:)-zue(:,jlev))
      zue_ad(:,jlev) = zue_ad(:,jlev)-zdudt_ad(:,jlev)*zau(:)
      zup_ad(:) = zup_ad(:)+zdudt_ad(:,jlev)*zau(:)
      zdudt_ad(:,jlev) = 0.
    end where
  end do
  where (zsums(:) > 0.)
    zvp_ad(:) = zvp_ad(:)/zsums(:)
    zup_ad(:) = zup_ad(:)/zsums(:)
  end where
  do jlev = nlev, 1, -1
    where (ilift(:) >= jlev .and. itop(:) <= jlev .and. zi(:) > 0. .and. ishallow(:) == 0)
      zve_ad(:,jlev) = zve_ad(:,jlev)+zvp_ad(:)*dsigma(jlev)
      zue_ad(:,jlev) = zue_ad(:,jlev)+zup_ad(:)*dsigma(jlev)
    end where
  end do
  where (zpt(:)+zpq(:) > 0.)
    zi_ad(:) = zi_ad(:)+zau_ad(:)*((0.5-sign(0.5,zi(:)/(zpt(:)+zpq(:))-1.))/(zpt(:)+zpq(:)))
    zpq_ad(:) = zpq_ad(:)-zau_ad(:)*(0.5-sign(0.5,zi(:)/(zpt(:)+zpq(:))-1.))*(zi(:)/(zpt(:)+zpq(:))/(zpt(:)+zpq(:)))
    zpt_ad(:) = zpt_ad(:)-zau_ad(:)*(0.5-sign(0.5,zi(:)/(zpt(:)+zpq(:))-1.))*(zi(:)/(zpt(:)+zpq(:))/(zpt(:)+zpq(:)))
    zau_ad(:) = 0.
  end where
  dv_ad(:,1:nlev) = dv_ad(:,1:nlev)+zve_ad(:,:)
  dvdt_ad(:,1:nlev) = dvdt_ad(:,1:nlev)+zve_ad(:,:)*deltsec2
  zve_ad(:,:) = 0.
  du_ad(:,1:nlev) = du_ad(:,1:nlev)+zue_ad(:,:)
  dudt_ad(:,1:nlev) = dudt_ad(:,1:nlev)+zue_ad(:,:)*deltsec2
  zue_ad(:,:) = 0.
endif
!$taf INCOMPLETE dqdt_ad,dtdt_ad
if (nshallow == 1) then
  read(unit=164,rec=1+subcl_ad(4,5)) itop
  zdqdts_ad(:,1:nlev) = zdqdts_ad(:,1:nlev)+dqdt_ad(:,1:nlev)
  zdtdts_ad(:,1:nlev) = zdtdts_ad(:,1:nlev)+dtdt_ad(:,1:nlev)
  call mkshallow_ad( zte,zte_ad,zqe,zqe_ad,ishallow,ilift,itop,zdtdts_ad,zdqdts_ad )
endif
!$taf INCOMPLETE dqdt_ad,dtdt_ad
do jlev = nlev, 1, -1
  ideep(:) = 0
  call getkey( 5,6,0,(-1)+jlev,subcl_ad(5,5),nrec )
  read(unit=165,rec=nrec) itop
  call getkey( 5,5,0,(-1)+jlev,subcl_ad(5,5),nrec )
  read(unit=166,rec=nrec) ilift
  where (ilift(:) >= jlev .and. itop(:) <= jlev .and. zi(:) > 0. .and. ishallow(:) == 0.)
    ideep(:) = 1
  end where
  where (ideep(:) > 0)
    zalcpe_ad(:,jlev) = zalcpe_ad(:,jlev)-dprcl_ad(:,jlev)*(zat(:)*zdtdt(:,jlev)*dsigma(jlev)/zalcpe(:,jlev)/zalcpe(:,jlev)/&
&deltsec2)
    zat_ad(:) = zat_ad(:)+dprcl_ad(:,jlev)*(zdtdt(:,jlev)*dsigma(jlev)/zalcpe(:,jlev)/deltsec2)
    zdtdt_ad(:,jlev) = zdtdt_ad(:,jlev)+dprcl_ad(:,jlev)*(zat(:)*dsigma(jlev)/zalcpe(:,jlev)/deltsec2)
    dprcl_ad(:,jlev) = 0.
    zat_ad(:) = zat_ad(:)+dtdt_ad(:,jlev)*(zdtdt(:,jlev)/deltsec2)
    zdtdt_ad(:,jlev) = zdtdt_ad(:,jlev)+dtdt_ad(:,jlev)*(zat(:)/deltsec2)
    dqt_ad(:,jlev) = dqt_ad(:,jlev)-dqdt_ad(:,jlev)
    zaq_ad(:) = zaq_ad(:)+dqdt_ad(:,jlev)*(zdqdt(:,jlev)/deltsec2)
    zdqdt_ad(:,jlev) = zdqdt_ad(:,jlev)+dqdt_ad(:,jlev)*(zaq(:)/deltsec2)
    dqdt_ad(:,jlev) = 0.
  end where
end do
if (nshallow == 1) then
  read(unit=167,rec=1+subcl_ad(4,5)) itop
  where (itop(:) > 0)
    dp_ad(:) = dp_ad(:)+zptop_ad(:)*sigma(itop(:))
    zptop_ad(:) = 0.
  end where
endif
!$taf INCOMPLETE zbeta_ad
if (kbeta == 0) then
  where (zpt(:)+zpq(:) > 0.)
    zat_ad(:) = zat_ad(:)+zaq_ad(:)
    zaq_ad(:) = 0.
    zi_ad(:) = zi_ad(:)+zat_ad(:)/(zpt(:)+zpq(:))
    zpq_ad(:) = zpq_ad(:)-zat_ad(:)*(zi(:)/(zpt(:)+zpq(:))/(zpt(:)+zpq(:)))
    zpt_ad(:) = zpt_ad(:)-zat_ad(:)*(zi(:)/(zpt(:)+zpq(:))/(zpt(:)+zpq(:)))
    zat_ad(:) = 0.
  end where
else
!$taf INCOMPLETE zbeta_ad
  zrhm(:) = 0.
  where (zpbeta(:) > 0.)
    zrhm(:) = zbeta(:)/zpbeta(:)
  end where
  zbeta(:) = 1.
  where (zrhm(:) >= rhbeta)
    zbeta(:) = ((1.-zrhm(:))/(1.-rhbeta))**nbeta
  end where
  if (kbeta == 2) then
    zbeta(:) = rbeta
  endif
  where (zpq(:) > 0.)
    zbeta_ad(:) = zbeta_ad(:)+zaq_ad(:)*(zi(:)/zpq(:))
    zi_ad(:) = zi_ad(:)+zaq_ad(:)*(zbeta(:)/zpq(:))
    zpq_ad(:) = zpq_ad(:)-zaq_ad(:)*(zi(:)*zbeta(:)/zpq(:)/zpq(:))
    zaq_ad(:) = 0.
  end where
  where (zpt(:) > 0.)
    zbeta_ad(:) = zbeta_ad(:)-zat_ad(:)*(zi(:)/zpt(:))
    zi_ad(:) = zi_ad(:)+zat_ad(:)*((1.-zbeta(:))/zpt(:))
    zpt_ad(:) = zpt_ad(:)-zat_ad(:)*(zi(:)*(1.-zbeta(:))/zpt(:)/zpt(:))
    zat_ad(:) = 0.
  end where
!$taf INCOMPLETE zbeta_ad
  if (kbeta == 2) then
    zbeta_ad(:) = 0.
  endif
  where (zrhm(:) >= rhbeta)
    zrhm_ad(:) = zrhm_ad(:)+(-(zbeta_ad(:)/(1.-rhbeta)))*nbeta*((1.-zrhm(:))/(1.-rhbeta))**(nbeta-1)
    zbeta_ad(:) = 0.
  end where
  zbeta_ad(:) = 0.
  where (zpbeta(:) > 0.)
    zbeta_ad(:) = zbeta_ad(:)+zrhm_ad(:)/zpbeta(:)
    zrhm_ad(:) = 0.
  end where
endif
read(unit=170,rec=1+subcl_ad(4,5)) zi
zi_ad(:) = zi_ad(:)*(0.5-sign(0.5,0.-zi(:)))
!$taf INCOMPLETE ztp_ad
do jlev = 1, nlem
!$taf INCOMPLETE zbeta_ad,zdqdt_ad,zdtdt_ad,zi_ad,zpq_ad,zpt_ad,ztp_ad
  jlep = jlev+1
  zfac = (sigma(jlev)/sigma(jlep))**akap
  call getkey( 5,4,0,nlem-jlev,subcl_ad(5,5),nrec )
  read(unit=175,rec=nrec) ztp
  call getkey( 5,3,0,nlem-jlev,subcl_ad(5,5),nrec )
  read(unit=176,rec=nrec) zqp
  call getkey( 5,2,0,nlem-jlev,subcl_ad(5,5),nrec )
  read(unit=177,rec=nrec) itop
!$taf INCOMPLETE zbeta_ad,zdqdt_ad,zdtdt_ad,zi_ad,zpq_ad,zpt_ad,ztp_ad
  do jhor = 1, nhor
    zcor_ad = 0.
    zdqsdt_ad = 0.
    zlcp_ad = 0.
    zqnew10_ad = 0.
    zqnew11_ad = 0.
    zqnew12_ad = 0.
    zqsa_ad = 0.
    zqsnl_ad = 0.
    zrain_ad = 0.
    ztnew10_ad = 0.
    ztnew11_ad = 0.
    ztnew12_ad = 0.
!$taf INCOMPLETE zbeta_ad,zdqdt_ad,zdtdt_ad,zi_ad,zpq_ad,zpt_ad,ztp_ad
    if (jlep == itop(jhor)) then
!$taf INCOMPLETE zbeta_ad,zdqdt_ad,zdtdt_ad,zi_ad,zpq_ad,zpt_ad,ztp_ad
      ztnew10 = ztp(jhor)*zfac
      zqnew10 = zqp(jhor)
      zqsnl = rdbrv*ra1*exp(ra2*(ztnew10-tmelt)/(ztnew10-ra4))/(dp(jhor)*sigma(jlev))
      zqsnl = amin1(zqsnl,rdbrv)
      zcor = 1./(1.-(1./rdbrv-1.)*zqsnl)
      zqsnl = zqsnl*zcor
!$taf INCOMPLETE zbeta_ad,zdqdt_ad,zdtdt_ad,zi_ad,zpq_ad,zpt_ad,ztp_ad
      if (zqsnl < zqnew10) then
!$taf INCOMPLETE zbeta_ad,zdqdt_ad,zdtdt_ad,zi_ad,zpq_ad,zpt_ad,zqp_ad,ztp_ad
        if (ztnew10 < tmelt) then
          zlcp = als/(acpd*(1.+adv*zqnew10))
        else
          zlcp = alv/(acpd*(1.+adv*zqnew10))
        endif
        zdqsdt = ra2*(tmelt-ra4)*zqsnl*zcor/((ztnew10-ra4)*(ztnew10-ra4))
        zrain = (zqnew10-zqsnl)/(1.+zlcp*zdqsdt)
        ztnew11 = ztnew10+zlcp*zrain
        zqnew11 = zqnew10-zrain
        zqsnl = rdbrv*ra1*exp(ra2*(ztnew11-tmelt)/(ztnew11-ra4))/(dp(jhor)*sigma(jlev))
        zqsnl = amin1(zqsnl,rdbrv)
        zcor = 1./(1.-(1./rdbrv-1.)*zqsnl)
        zqsnl = zqsnl*zcor
        zdqsdt = ra2*(tmelt-ra4)*zqsnl*zcor/((ztnew11-ra4)*(ztnew11-ra4))
        zrain = (zqnew11-zqsnl)/(1.+zlcp*zdqsdt)
        ztnew12 = ztnew11+zlcp*zrain
!$taf INCOMPLETE zbeta_ad,zdqdt_ad,zdtdt_ad,zi_ad,zpq_ad,zpt_ad,zqp_ad,ztp_ad
        if (ztnew12 > zte(jhor,jlev)) then
!$taf INCOMPLETE zbeta_ad,zdtdt,zpq_ad,zpt_ad,ztp
          ztp(jhor) = ztnew12
          zqsa = rdbrv*ra1*exp(ra2*(zte(jhor,jlev)-tmelt)/(zte(jhor,jlev)-ra4))/(dp(jhor)*sigma(jlev))
          zqsa = amin1(zqsa,rdbrv)
          zqsa = zqsa/(1.-(1./rdbrv-1.)*zqsa)
          zdtdt(jhor,jlev) = ztp(jhor)-zte(jhor,jlev)
          zdqtot_ad(jhor,jlev) = zdqtot_ad(jhor,jlev)+zi_ad(jhor)*dsigma(jlev)*zale(jhor,jlev)
!$taf INCOMPLETE zbeta_ad,zpq_ad,zpt_ad
          if (kbeta > 0) then
            zbetah_ad = 0._8
            zbetai_ad = zbeta_ad(jhor)*dsigma(jlev)
            zbetah_ad = zbetai_ad*(0.5-sign(0.5,zqe(jhor,jlev)/zqsa-1.))
            zqe_ad(jhor,jlev) = zqe_ad(jhor,jlev)+zbetah_ad/zqsa
            zqsa_ad = zqsa_ad-zbetah_ad*(zqe(jhor,jlev)/zqsa/zqsa)
          endif
          zdqdt_ad(jhor,jlev) = zdqdt_ad(jhor,jlev)+zpq_ad(jhor)*dsigma(jlev)*zale(jhor,jlev)
          zacpe_ad(jhor,jlev) = zacpe_ad(jhor,jlev)+zpt_ad(jhor)*zdtdt(jhor,jlev)*dsigma(jlev)
          zdtdt_ad(jhor,jlev) = zdtdt_ad(jhor,jlev)+zpt_ad(jhor)*dsigma(jlev)*zacpe(jhor,jlev)
          zte_ad(jhor,jlev) = zte_ad(jhor,jlev)-zdtdt_ad(jhor,jlev)
          ztp_ad(jhor) = ztp_ad(jhor)+zdtdt_ad(jhor,jlev)
          zdtdt_ad(jhor,jlev) = 0.
          zqe_ad(jhor,jlev) = zqe_ad(jhor,jlev)-zdqdt_ad(jhor,jlev)*(0.5+sign(0.5,zqsa-zqe(jhor,jlev)-0.))
          zqsa_ad = zqsa_ad+zdqdt_ad(jhor,jlev)*(0.5+sign(0.5,zqsa-zqe(jhor,jlev)-0.))
          zdqdt_ad(jhor,jlev) = 0.
          zqsa = rdbrv*ra1*exp(ra2*(zte(jhor,jlev)-tmelt)/(zte(jhor,jlev)-ra4))/(dp(jhor)*sigma(jlev))
          zqsa = amin1(zqsa,rdbrv)
          zqsa_ad = zqsa_ad*((1-zqsa*(1-1./rdbrv)/(1.-(1./rdbrv-1.)*zqsa))/(1.-(1./rdbrv-1.)*zqsa))
          zqsa = rdbrv*ra1*exp(ra2*(zte(jhor,jlev)-tmelt)/(zte(jhor,jlev)-ra4))/(dp(jhor)*sigma(jlev))
          zqsa_ad = zqsa_ad*(0.5+sign(0.5,rdbrv-zqsa))
          zqsah = ra2*(zte(jhor,jlev)-tmelt)/(zte(jhor,jlev)-ra4)
          dp_ad(jhor) = dp_ad(jhor)-zqsa_ad*(rdbrv*ra1*sigma(jlev)*exp(zqsah)/(dp(jhor)*sigma(jlev))/(dp(jhor)*sigma(jlev)))
          zte_ad(jhor,jlev) = zte_ad(jhor,jlev)+zqsa_ad*(rdbrv*ra1*exp(zqsah)/(dp(jhor)*sigma(jlev)))*((ra2-ra2*(zte(jhor,jlev)-&
&tmelt)/(zte(jhor,jlev)-ra4))/(zte(jhor,jlev)-ra4))
          zqsa_ad = 0.
          zqnew12_ad = zqnew12_ad+zqp_ad(jhor)
          zqp_ad(jhor) = 0.
          ztnew12_ad = ztnew12_ad+ztp_ad(jhor)
          ztp_ad(jhor) = 0.
        endif
        zqnew11_ad = zqnew11_ad+zqnew12_ad
        zrain_ad = zrain_ad-zqnew12_ad
        zqnew12_ad = 0.
        zlcp_ad = zlcp_ad+ztnew12_ad*zrain
        zrain_ad = zrain_ad+ztnew12_ad*zlcp
        ztnew11_ad = ztnew11_ad+ztnew12_ad
        ztnew12_ad = 0.
        zdqsdt_ad = zdqsdt_ad-zrain_ad*((zqnew11-zqsnl)*zlcp/(1.+zlcp*zdqsdt)/(1.+zlcp*zdqsdt))
        zlcp_ad = zlcp_ad-zrain_ad*((zqnew11-zqsnl)*zdqsdt/(1.+zlcp*zdqsdt)/(1.+zlcp*zdqsdt))
        zqnew11_ad = zqnew11_ad+zrain_ad/(1.+zlcp*zdqsdt)
        zqsnl_ad = zqsnl_ad-zrain_ad/(1.+zlcp*zdqsdt)
        zrain_ad = 0.
        zcor_ad = zcor_ad+zdqsdt_ad*(ra2*(tmelt-ra4)*zqsnl/((ztnew11-ra4)*(ztnew11-ra4)))
        zqsnl_ad = zqsnl_ad+zdqsdt_ad*(ra2*(tmelt-ra4)*zcor/((ztnew11-ra4)*(ztnew11-ra4)))
        ztnew11_ad = ztnew11_ad-zdqsdt_ad*(2*(ra2*(tmelt-ra4)*zqsnl*zcor)*(ztnew11-ra4)/((ztnew11-ra4)*(ztnew11-ra4))/((ztnew11-&
&ra4)*(ztnew11-ra4)))
        zdqsdt_ad = 0.
        zqsnl = rdbrv*ra1*exp(ra2*(ztnew11-tmelt)/(ztnew11-ra4))/(dp(jhor)*sigma(jlev))
        zqsnl = amin1(zqsnl,rdbrv)
        zcor_ad = zcor_ad+zqsnl_ad*zqsnl
        zqsnl_ad = zqsnl_ad*zcor
        zqsnl = rdbrv*ra1*exp(ra2*(ztnew11-tmelt)/(ztnew11-ra4))/(dp(jhor)*sigma(jlev))
        zqsnl = amin1(zqsnl,rdbrv)
        zqsnl_ad = zqsnl_ad-zcor_ad*(1.*(1-1./rdbrv)/(1.-(1./rdbrv-1.)*zqsnl)/(1.-(1./rdbrv-1.)*zqsnl))
        zcor_ad = 0.
        zqsnl = rdbrv*ra1*exp(ra2*(ztnew11-tmelt)/(ztnew11-ra4))/(dp(jhor)*sigma(jlev))
        zqsnl_ad = zqsnl_ad*(0.5+sign(0.5,rdbrv-zqsnl))
        zqsnlh = ra2*(ztnew11-tmelt)/(ztnew11-ra4)
        dp_ad(jhor) = dp_ad(jhor)-zqsnl_ad*(rdbrv*ra1*sigma(jlev)*exp(zqsnlh)/(dp(jhor)*sigma(jlev))/(dp(jhor)*sigma(jlev)))
        ztnew11_ad = ztnew11_ad+zqsnl_ad*(rdbrv*ra1*exp(zqsnlh)/(dp(jhor)*sigma(jlev)))*((ra2-ra2*(ztnew11-tmelt)/(ztnew11-ra4))/&
&(ztnew11-ra4))
        zqsnl_ad = 0.
        zqnew10_ad = zqnew10_ad+zqnew11_ad
        zrain_ad = zrain_ad-zqnew11_ad
        zqnew11_ad = 0.
        zqsnl = rdbrv*ra1*exp(ra2*(ztnew10-tmelt)/(ztnew10-ra4))/(dp(jhor)*sigma(jlev))
        zqsnl = amin1(zqsnl,rdbrv)
        zcor = 1./(1.-(1./rdbrv-1.)*zqsnl)
        zqsnl = zqsnl*zcor
        zdqsdt = ra2*(tmelt-ra4)*zqsnl*zcor/((ztnew10-ra4)*(ztnew10-ra4))
        zrain = (zqnew10-zqsnl)/(1.+zlcp*zdqsdt)
        zlcp_ad = zlcp_ad+ztnew11_ad*zrain
        zrain_ad = zrain_ad+ztnew11_ad*zlcp
        ztnew10_ad = ztnew10_ad+ztnew11_ad
        ztnew11_ad = 0.
        zqsnl = rdbrv*ra1*exp(ra2*(ztnew10-tmelt)/(ztnew10-ra4))/(dp(jhor)*sigma(jlev))
        zqsnl = amin1(zqsnl,rdbrv)
        zcor = 1./(1.-(1./rdbrv-1.)*zqsnl)
        zqsnl = zqsnl*zcor
        zdqsdt = ra2*(tmelt-ra4)*zqsnl*zcor/((ztnew10-ra4)*(ztnew10-ra4))
        zdqsdt_ad = zdqsdt_ad-zrain_ad*((zqnew10-zqsnl)*zlcp/(1.+zlcp*zdqsdt)/(1.+zlcp*zdqsdt))
        zlcp_ad = zlcp_ad-zrain_ad*((zqnew10-zqsnl)*zdqsdt/(1.+zlcp*zdqsdt)/(1.+zlcp*zdqsdt))
        zqnew10_ad = zqnew10_ad+zrain_ad/(1.+zlcp*zdqsdt)
        zqsnl_ad = zqsnl_ad-zrain_ad/(1.+zlcp*zdqsdt)
        zrain_ad = 0.
        zqsnl = rdbrv*ra1*exp(ra2*(ztnew10-tmelt)/(ztnew10-ra4))/(dp(jhor)*sigma(jlev))
        zqsnl = amin1(zqsnl,rdbrv)
        zcor = 1./(1.-(1./rdbrv-1.)*zqsnl)
        zqsnl = zqsnl*zcor
        zcor_ad = zcor_ad+zdqsdt_ad*(ra2*(tmelt-ra4)*zqsnl/((ztnew10-ra4)*(ztnew10-ra4)))
        zqsnl_ad = zqsnl_ad+zdqsdt_ad*(ra2*(tmelt-ra4)*zcor/((ztnew10-ra4)*(ztnew10-ra4)))
        ztnew10_ad = ztnew10_ad-zdqsdt_ad*(2*(ra2*(tmelt-ra4)*zqsnl*zcor)*(ztnew10-ra4)/((ztnew10-ra4)*(ztnew10-ra4))/((ztnew10-&
&ra4)*(ztnew10-ra4)))
        zdqsdt_ad = 0.
        if (ztnew10 < tmelt) then
          zqnew10_ad = zqnew10_ad-zlcp_ad*(als*acpd*adv/(acpd*(1.+adv*zqnew10))/(acpd*(1.+adv*zqnew10)))
          zlcp_ad = 0.
        else
          zqnew10_ad = zqnew10_ad-zlcp_ad*(alv*acpd*adv/(acpd*(1.+adv*zqnew10))/(acpd*(1.+adv*zqnew10)))
          zlcp_ad = 0.
        endif
      endif
      zqsnl = rdbrv*ra1*exp(ra2*(ztnew10-tmelt)/(ztnew10-ra4))/(dp(jhor)*sigma(jlev))
      zqsnl = amin1(zqsnl,rdbrv)
      zcor = 1./(1.-(1./rdbrv-1.)*zqsnl)
      zcor_ad = zcor_ad+zqsnl_ad*zqsnl
      zqsnl_ad = zqsnl_ad*zcor
      zqsnl = rdbrv*ra1*exp(ra2*(ztnew10-tmelt)/(ztnew10-ra4))/(dp(jhor)*sigma(jlev))
      zqsnl = amin1(zqsnl,rdbrv)
      zqsnl_ad = zqsnl_ad-zcor_ad*(1.*(1-1./rdbrv)/(1.-(1./rdbrv-1.)*zqsnl)/(1.-(1./rdbrv-1.)*zqsnl))
      zcor_ad = 0.
      zqsnl = rdbrv*ra1*exp(ra2*(ztnew10-tmelt)/(ztnew10-ra4))/(dp(jhor)*sigma(jlev))
      zqsnl_ad = zqsnl_ad*(0.5+sign(0.5,rdbrv-zqsnl))
      zqsnli = ra2*(ztnew10-tmelt)/(ztnew10-ra4)
      dp_ad(jhor) = dp_ad(jhor)-zqsnl_ad*(rdbrv*ra1*sigma(jlev)*exp(zqsnli)/(dp(jhor)*sigma(jlev))/(dp(jhor)*sigma(jlev)))
      ztnew10_ad = ztnew10_ad+zqsnl_ad*(rdbrv*ra1*exp(zqsnli)/(dp(jhor)*sigma(jlev)))*((ra2-ra2*(ztnew10-tmelt)/(ztnew10-ra4))/&
&(ztnew10-ra4))
      zqsnl_ad = 0.
      zqp_ad(jhor) = zqp_ad(jhor)+zqnew10_ad
      zqnew10_ad = 0.
      ztp_ad(jhor) = ztp_ad(jhor)+ztnew10_ad*zfac
      ztnew10_ad = 0.
    endif
  end do
end do
dtdt = dtdth(:,:)
zte(:,:) = dt(:,1:nlev)+dtdt(:,1:nlev)*deltsec2
do jlev = 1, nlem
  jlep = jlev+1
  zfac = (sigma(jlev)/sigma(jlep))**akap
  call getkey( 5,1,0,nlem-jlev,subcl_ad(5,5),nrec )
  read(unit=180,rec=nrec) ilift
  do jhor = 1, nhor
    zcor_ad = 0.
    zdqsdt_ad = 0.
    zlcp_ad = 0.
    zqnew4_ad = 0.
    zqnew5_ad = 0.
    zqnew6_ad = 0.
    zqnew7_ad = 0.
    zqnew8_ad = 0.
    zqnew9_ad = 0.
    zqsa_ad = 0.
    zqsnl_ad = 0.
    zrain_ad = 0.
    ztnew4_ad = 0.
    ztnew5_ad = 0.
    ztnew6_ad = 0.
    ztnew7_ad = 0.
    ztnew8_ad = 0.
    ztnew9_ad = 0.
!$taf INCOMPLETE zdqdt_ad,zdtdt_ad,zpt_ad,zqp_ad,ztp_ad
    if (ilift(jhor) == (-1) .and. zdqtot(jhor,jlep) > 0.) then
!$taf INCOMPLETE zdqdt_ad,zdtdt_ad,zpt_ad,zqp_ad,ztp_ad
      ztnew4 = zte(jhor,jlep)*zfac
      zqnew4 = zqe(jhor,jlep)
      zqsnl = rdbrv*ra1*exp(ra2*(ztnew4-tmelt)/(ztnew4-ra4))/(dp(jhor)*sigma(jlev))
      zqsnl = amin1(zqsnl,rdbrv)
      zcor = 1./(1.-(1./rdbrv-1.)*zqsnl)
      zqsnl = zqsnl*zcor
!$taf INCOMPLETE zdqdt_ad,zdtdt_ad,zpt_ad,zqp_ad,ztp_ad
      if (zqsnl < zqnew4) then
!$taf INCOMPLETE zdqdt_ad,zdtdt_ad,zpt_ad,zqp_ad,ztp_ad
        if (ztnew4 < tmelt) then
          zlcp = als/(acpd*(1.+adv*zqnew4))
        else
          zlcp = alv/(acpd*(1.+adv*zqnew4))
        endif
        zdqsdt = ra2*(tmelt-ra4)*zqsnl*zcor/((ztnew4-ra4)*(ztnew4-ra4))
        zrain = (zqnew4-zqsnl)/(1.+zlcp*zdqsdt)
        ztnew5 = ztnew4+zlcp*zrain
        zqnew5 = zqnew4-zrain
        zqsnl = rdbrv*ra1*exp(ra2*(ztnew5-tmelt)/(ztnew5-ra4))/(dp(jhor)*sigma(jlev))
        zqsnl = amin1(zqsnl,rdbrv)
        zcor = 1./(1.-(1./rdbrv-1.)*zqsnl)
        zqsnl = zqsnl*zcor
        zdqsdt = ra2*(tmelt-ra4)*zqsnl*zcor/((ztnew5-ra4)*(ztnew5-ra4))
        zrain = (zqnew5-zqsnl)/(1.+zlcp*zdqsdt)
        ztnew6 = ztnew5+zlcp*zrain
!$taf INCOMPLETE zdqdt_ad,zdtdt_ad,zpt_ad,zqp_ad,ztp_ad
        if (ztnew6 > zte(jhor,jlev)) then
!$taf INCOMPLETE zdtdt,ztp
          ztp(jhor) = ztnew6
          zqsa = rdbrv*ra1*exp(ra2*(zte(jhor,jlev)-tmelt)/(zte(jhor,jlev)-ra4))/(dp(jhor)*sigma(jlev))
          zqsa = amin1(zqsa,rdbrv)
          zqsa = zqsa/(1.-(1./rdbrv-1.)*zqsa)
          zdtdt(jhor,jlev) = ztp(jhor)-zte(jhor,jlev)
          ztnew7 = zte(jhor,jlep)
          zqnew7 = zqe(jhor,jlep)
          zqsnl = rdbrv*ra1*exp(ra2*(zte(jhor,jlep)-tmelt)/(zte(jhor,jlep)-ra4))/(dp(jhor)*sigma(jlep))
          zqsnl = amin1(zqsnl,rdbrv)
          zqsnl = zqsnl/(1.-(1./rdbrv-1.)*zqsnl)
          zdqtot_ad(jhor,jlep) = zdqtot_ad(jhor,jlep)+zi_ad(jhor)*dsigma(jlep)*zale(jhor,jlep)
          zdqtot_ad(jhor,jlev) = zdqtot_ad(jhor,jlev)+zi_ad(jhor)*dsigma(jlev)*zale(jhor,jlev)
          zi_ad(jhor) = 0.
!$taf INCOMPLETE zdtdt
          if (zqe(jhor,jlep) > zqsnl) then
!$taf INCOMPLETE zdtdt
            if (ztnew7 < tmelt) then
              zlcp = als/(acpd*(1.+adv*zqnew7))
            else
              zlcp = alv/(acpd*(1.+adv*zqnew7))
            endif
            zdqsdt = ra2*(tmelt-ra4)*zqsnl*zcor/((ztnew7-ra4)*(ztnew7-ra4))
            zrain = (zqnew7-zqsnl)/(1.+zlcp*zdqsdt)
            ztnew8 = ztnew7+zlcp*zrain
            zqnew8 = zqnew7-zrain
            zqsnl = rdbrv*ra1*exp(ra2*(ztnew8-tmelt)/(ztnew8-ra4))/(dp(jhor)*sigma(jlep))
            zqsnl = amin1(zqsnl,rdbrv)
            zcor = 1./(1.-(1./rdbrv-1.)*zqsnl)
            zqsnl = zqsnl*zcor
            zdqsdt = ra2*(tmelt-ra4)*zqsnl*zcor/((ztnew8-ra4)*(ztnew8-ra4))
            zrain = (zqnew8-zqsnl)/(1.+zlcp*zdqsdt)
            ztnew9 = ztnew8+zlcp*zrain
            zqnew9 = zqnew8-zrain
            zdtdt(jhor,jlep) = ztnew9-zte(jhor,jlep)
            if (kbeta > 0) then
              zbetah_ae = 0._8
              zbetaj_ad = zbeta_ad(jhor)*dsigma(jlep)
              zbetah_ae = zbetaj_ad*(0.5-sign(0.5,zqe(jhor,jlep)/zqsnl-1.))
              zqe_ad(jhor,jlep) = zqe_ad(jhor,jlep)+zbetah_ae/zqsnl
              zqsnl_ad = zqsnl_ad-zbetah_ae*(zqe(jhor,jlep)/zqsnl/zqsnl)
            endif
            zdqdt_ad(jhor,jlep) = zdqdt_ad(jhor,jlep)+zpq_ad(jhor)*dsigma(jlep)*zale(jhor,jlep)
            zacpe_ad(jhor,jlep) = zacpe_ad(jhor,jlep)+zpt_ad(jhor)*zdtdt(jhor,jlep)*dsigma(jlep)
            zdtdt_ad(jhor,jlep) = zdtdt_ad(jhor,jlep)+zpt_ad(jhor)*dsigma(jlep)*zacpe(jhor,jlep)
            zte_ad(jhor,jlep) = zte_ad(jhor,jlep)-zdtdt_ad(jhor,jlep)
            ztnew9_ad = ztnew9_ad+zdtdt_ad(jhor,jlep)
            zdtdt_ad(jhor,jlep) = 0.
            zqe_ad(jhor,jlep) = zqe_ad(jhor,jlep)-zdqdt_ad(jhor,jlep)*(0.5+sign(0.5,zqnew9-zqe(jhor,jlep)-0.))
            zqnew9_ad = zqnew9_ad+zdqdt_ad(jhor,jlep)*(0.5+sign(0.5,zqnew9-zqe(jhor,jlep)-0.))
            zdqdt_ad(jhor,jlep) = 0.
            zqnew8_ad = zqnew8_ad+zqnew9_ad
            zrain_ad = zrain_ad-zqnew9_ad
            zqnew9_ad = 0.
            zlcp_ad = zlcp_ad+ztnew9_ad*zrain
            zrain_ad = zrain_ad+ztnew9_ad*zlcp
            ztnew8_ad = ztnew8_ad+ztnew9_ad
            ztnew9_ad = 0.
            zdqsdt_ad = zdqsdt_ad-zrain_ad*((zqnew8-zqsnl)*zlcp/(1.+zlcp*zdqsdt)/(1.+zlcp*zdqsdt))
            zlcp_ad = zlcp_ad-zrain_ad*((zqnew8-zqsnl)*zdqsdt/(1.+zlcp*zdqsdt)/(1.+zlcp*zdqsdt))
            zqnew8_ad = zqnew8_ad+zrain_ad/(1.+zlcp*zdqsdt)
            zqsnl_ad = zqsnl_ad-zrain_ad/(1.+zlcp*zdqsdt)
            zrain_ad = 0.
            zcor_ad = zcor_ad+zdqsdt_ad*(ra2*(tmelt-ra4)*zqsnl/((ztnew8-ra4)*(ztnew8-ra4)))
            zqsnl_ad = zqsnl_ad+zdqsdt_ad*(ra2*(tmelt-ra4)*zcor/((ztnew8-ra4)*(ztnew8-ra4)))
            ztnew8_ad = ztnew8_ad-zdqsdt_ad*(2*(ra2*(tmelt-ra4)*zqsnl*zcor)*(ztnew8-ra4)/((ztnew8-ra4)*(ztnew8-ra4))/((ztnew8-ra4)*&
&(ztnew8-ra4)))
            zdqsdt_ad = 0.
            zqsnl = rdbrv*ra1*exp(ra2*(ztnew8-tmelt)/(ztnew8-ra4))/(dp(jhor)*sigma(jlep))
            zqsnl = amin1(zqsnl,rdbrv)
            zcor_ad = zcor_ad+zqsnl_ad*zqsnl
            zqsnl_ad = zqsnl_ad*zcor
            zqsnl = rdbrv*ra1*exp(ra2*(ztnew8-tmelt)/(ztnew8-ra4))/(dp(jhor)*sigma(jlep))
            zqsnl = amin1(zqsnl,rdbrv)
            zqsnl_ad = zqsnl_ad-zcor_ad*(1.*(1-1./rdbrv)/(1.-(1./rdbrv-1.)*zqsnl)/(1.-(1./rdbrv-1.)*zqsnl))
            zcor_ad = 0.
            zqsnl = rdbrv*ra1*exp(ra2*(ztnew8-tmelt)/(ztnew8-ra4))/(dp(jhor)*sigma(jlep))
            zqsnl_ad = zqsnl_ad*(0.5+sign(0.5,rdbrv-zqsnl))
            zqsnlj = ra2*(ztnew8-tmelt)/(ztnew8-ra4)
            dp_ad(jhor) = dp_ad(jhor)-zqsnl_ad*(rdbrv*ra1*sigma(jlep)*exp(zqsnlj)/(dp(jhor)*sigma(jlep))/(dp(jhor)*sigma(jlep)))
            ztnew8_ad = ztnew8_ad+zqsnl_ad*(rdbrv*ra1*exp(zqsnlj)/(dp(jhor)*sigma(jlep)))*((ra2-ra2*(ztnew8-tmelt)/(ztnew8-ra4))/&
&(ztnew8-ra4))
            zqsnl_ad = 0.
            zqnew7_ad = zqnew7_ad+zqnew8_ad
            zrain_ad = zrain_ad-zqnew8_ad
            zqnew8_ad = 0.
            zqsnl = rdbrv*ra1*exp(ra2*(ztnew5-tmelt)/(ztnew5-ra4))/(dp(jhor)*sigma(jlev))
            zqsnl = amin1(zqsnl,rdbrv)
            zcor = 1./(1.-(1./rdbrv-1.)*zqsnl)
            zqsnl = rdbrv*ra1*exp(ra2*(zte(jhor,jlep)-tmelt)/(zte(jhor,jlep)-ra4))/(dp(jhor)*sigma(jlep))
            zqsnl = amin1(zqsnl,rdbrv)
            zqsnl = zqsnl/(1.-(1./rdbrv-1.)*zqsnl)
            zdqsdt = ra2*(tmelt-ra4)*zqsnl*zcor/((ztnew7-ra4)*(ztnew7-ra4))
            zrain = (zqnew7-zqsnl)/(1.+zlcp*zdqsdt)
            zlcp_ad = zlcp_ad+ztnew8_ad*zrain
            zrain_ad = zrain_ad+ztnew8_ad*zlcp
            ztnew7_ad = ztnew7_ad+ztnew8_ad
            ztnew8_ad = 0.
            zqsnl = rdbrv*ra1*exp(ra2*(ztnew5-tmelt)/(ztnew5-ra4))/(dp(jhor)*sigma(jlev))
            zqsnl = amin1(zqsnl,rdbrv)
            zcor = 1./(1.-(1./rdbrv-1.)*zqsnl)
            zqsnl = rdbrv*ra1*exp(ra2*(zte(jhor,jlep)-tmelt)/(zte(jhor,jlep)-ra4))/(dp(jhor)*sigma(jlep))
            zqsnl = amin1(zqsnl,rdbrv)
            zqsnl = zqsnl/(1.-(1./rdbrv-1.)*zqsnl)
            zdqsdt = ra2*(tmelt-ra4)*zqsnl*zcor/((ztnew7-ra4)*(ztnew7-ra4))
            zdqsdt_ad = zdqsdt_ad-zrain_ad*((zqnew7-zqsnl)*zlcp/(1.+zlcp*zdqsdt)/(1.+zlcp*zdqsdt))
            zlcp_ad = zlcp_ad-zrain_ad*((zqnew7-zqsnl)*zdqsdt/(1.+zlcp*zdqsdt)/(1.+zlcp*zdqsdt))
            zqnew7_ad = zqnew7_ad+zrain_ad/(1.+zlcp*zdqsdt)
            zqsnl_ad = zqsnl_ad-zrain_ad/(1.+zlcp*zdqsdt)
            zrain_ad = 0.
            zqsnl = rdbrv*ra1*exp(ra2*(ztnew5-tmelt)/(ztnew5-ra4))/(dp(jhor)*sigma(jlev))
            zqsnl = amin1(zqsnl,rdbrv)
            zcor = 1./(1.-(1./rdbrv-1.)*zqsnl)
            zqsnl = rdbrv*ra1*exp(ra2*(zte(jhor,jlep)-tmelt)/(zte(jhor,jlep)-ra4))/(dp(jhor)*sigma(jlep))
            zqsnl = amin1(zqsnl,rdbrv)
            zqsnl = zqsnl/(1.-(1./rdbrv-1.)*zqsnl)
            zcor_ad = zcor_ad+zdqsdt_ad*(ra2*(tmelt-ra4)*zqsnl/((ztnew7-ra4)*(ztnew7-ra4)))
            zqsnl_ad = zqsnl_ad+zdqsdt_ad*(ra2*(tmelt-ra4)*zcor/((ztnew7-ra4)*(ztnew7-ra4)))
            ztnew7_ad = ztnew7_ad-zdqsdt_ad*(2*(ra2*(tmelt-ra4)*zqsnl*zcor)*(ztnew7-ra4)/((ztnew7-ra4)*(ztnew7-ra4))/((ztnew7-ra4)*&
&(ztnew7-ra4)))
            zdqsdt_ad = 0.
            if (ztnew7 < tmelt) then
              zqnew7_ad = zqnew7_ad-zlcp_ad*(als*acpd*adv/(acpd*(1.+adv*zqnew7))/(acpd*(1.+adv*zqnew7)))
              zlcp_ad = 0.
            else
              zqnew7_ad = zqnew7_ad-zlcp_ad*(alv*acpd*adv/(acpd*(1.+adv*zqnew7))/(acpd*(1.+adv*zqnew7)))
              zlcp_ad = 0.
            endif
          endif
          zqsnl = rdbrv*ra1*exp(ra2*(zte(jhor,jlep)-tmelt)/(zte(jhor,jlep)-ra4))/(dp(jhor)*sigma(jlep))
          zqsnl = amin1(zqsnl,rdbrv)
          zqsnl_ad = zqsnl_ad*((1-zqsnl*(1-1./rdbrv)/(1.-(1./rdbrv-1.)*zqsnl))/(1.-(1./rdbrv-1.)*zqsnl))
          zqsnl = rdbrv*ra1*exp(ra2*(zte(jhor,jlep)-tmelt)/(zte(jhor,jlep)-ra4))/(dp(jhor)*sigma(jlep))
          zqsnl_ad = zqsnl_ad*(0.5+sign(0.5,rdbrv-zqsnl))
          zqsnlk = ra2*(zte(jhor,jlep)-tmelt)/(zte(jhor,jlep)-ra4)
          dp_ad(jhor) = dp_ad(jhor)-zqsnl_ad*(rdbrv*ra1*sigma(jlep)*exp(zqsnlk)/(dp(jhor)*sigma(jlep))/(dp(jhor)*sigma(jlep)))
          zte_ad(jhor,jlep) = zte_ad(jhor,jlep)+zqsnl_ad*(rdbrv*ra1*exp(zqsnlk)/(dp(jhor)*sigma(jlep)))*((ra2-ra2*(zte(jhor,jlep)-&
&tmelt)/(zte(jhor,jlep)-ra4))/(zte(jhor,jlep)-ra4))
          zqsnl_ad = 0.
          zqe_ad(jhor,jlep) = zqe_ad(jhor,jlep)+zqnew7_ad
          zqnew7_ad = 0.
          zte_ad(jhor,jlep) = zte_ad(jhor,jlep)+ztnew7_ad
          ztnew7_ad = 0.
          if (kbeta > 0) then
            zbetah_af = 0._8
            zbetah_af = zbeta_ad(jhor)*dsigma(jlev)*(0.5-sign(0.5,zqe(jhor,jlev)/zqsa-1.))
            zqe_ad(jhor,jlev) = zqe_ad(jhor,jlev)+zbetah_af/zqsa
            zqsa_ad = zqsa_ad-zbetah_af*(zqe(jhor,jlev)/zqsa/zqsa)
            zbeta_ad(jhor) = 0.
          endif
          zdqdt_ad(jhor,jlev) = zdqdt_ad(jhor,jlev)+zpq_ad(jhor)*dsigma(jlev)*zale(jhor,jlev)
          zpq_ad(jhor) = 0.
          zdtdt(jhor,jlev) = ztp(jhor)-zte(jhor,jlev)
          zacpe_ad(jhor,jlev) = zacpe_ad(jhor,jlev)+zpt_ad(jhor)*zdtdt(jhor,jlev)*dsigma(jlev)
          zdtdt_ad(jhor,jlev) = zdtdt_ad(jhor,jlev)+zpt_ad(jhor)*dsigma(jlev)*zacpe(jhor,jlev)
          zpt_ad(jhor) = 0.
          zte_ad(jhor,jlev) = zte_ad(jhor,jlev)-zdtdt_ad(jhor,jlev)
          ztp_ad(jhor) = ztp_ad(jhor)+zdtdt_ad(jhor,jlev)
          zdtdt_ad(jhor,jlev) = 0.
          zqe_ad(jhor,jlev) = zqe_ad(jhor,jlev)-zdqdt_ad(jhor,jlev)*(0.5+sign(0.5,zqsa-zqe(jhor,jlev)-0.))
          zqsa_ad = zqsa_ad+zdqdt_ad(jhor,jlev)*(0.5+sign(0.5,zqsa-zqe(jhor,jlev)-0.))
          zdqdt_ad(jhor,jlev) = 0.
          zqsa = rdbrv*ra1*exp(ra2*(zte(jhor,jlev)-tmelt)/(zte(jhor,jlev)-ra4))/(dp(jhor)*sigma(jlev))
          zqsa = amin1(zqsa,rdbrv)
          zqsa_ad = zqsa_ad*((1-zqsa*(1-1./rdbrv)/(1.-(1./rdbrv-1.)*zqsa))/(1.-(1./rdbrv-1.)*zqsa))
          zqsa = rdbrv*ra1*exp(ra2*(zte(jhor,jlev)-tmelt)/(zte(jhor,jlev)-ra4))/(dp(jhor)*sigma(jlev))
          zqsa_ad = zqsa_ad*(0.5+sign(0.5,rdbrv-zqsa))
          zqsai = ra2*(zte(jhor,jlev)-tmelt)/(zte(jhor,jlev)-ra4)
          dp_ad(jhor) = dp_ad(jhor)-zqsa_ad*(rdbrv*ra1*sigma(jlev)*exp(zqsai)/(dp(jhor)*sigma(jlev))/(dp(jhor)*sigma(jlev)))
          zte_ad(jhor,jlev) = zte_ad(jhor,jlev)+zqsa_ad*(rdbrv*ra1*exp(zqsai)/(dp(jhor)*sigma(jlev)))*((ra2-ra2*(zte(jhor,jlev)-&
&tmelt)/(zte(jhor,jlev)-ra4))/(zte(jhor,jlev)-ra4))
          zqsa_ad = 0.
          zqnew6_ad = zqnew6_ad+zqp_ad(jhor)
          zqp_ad(jhor) = 0.
          ztnew6_ad = ztnew6_ad+ztp_ad(jhor)
          ztp_ad(jhor) = 0.
        endif
        zqnew5_ad = zqnew5_ad+zqnew6_ad
        zrain_ad = zrain_ad-zqnew6_ad
        zqnew6_ad = 0.
        if (ztnew4 < tmelt) then
          zlcp = als/(acpd*(1.+adv*zqnew4))
        else
          zlcp = alv/(acpd*(1.+adv*zqnew4))
        endif
        zqsnl = rdbrv*ra1*exp(ra2*(ztnew5-tmelt)/(ztnew5-ra4))/(dp(jhor)*sigma(jlev))
        zqsnl = amin1(zqsnl,rdbrv)
        zcor = 1./(1.-(1./rdbrv-1.)*zqsnl)
        zqsnl = zqsnl*zcor
        zdqsdt = ra2*(tmelt-ra4)*zqsnl*zcor/((ztnew5-ra4)*(ztnew5-ra4))
        zrain = (zqnew5-zqsnl)/(1.+zlcp*zdqsdt)
        zlcp_ad = zlcp_ad+ztnew6_ad*zrain
        zrain_ad = zrain_ad+ztnew6_ad*zlcp
        ztnew5_ad = ztnew5_ad+ztnew6_ad
        ztnew6_ad = 0.
        if (ztnew4 < tmelt) then
          zlcp = als/(acpd*(1.+adv*zqnew4))
        else
          zlcp = alv/(acpd*(1.+adv*zqnew4))
        endif
        zqsnl = rdbrv*ra1*exp(ra2*(ztnew5-tmelt)/(ztnew5-ra4))/(dp(jhor)*sigma(jlev))
        zqsnl = amin1(zqsnl,rdbrv)
        zcor = 1./(1.-(1./rdbrv-1.)*zqsnl)
        zqsnl = zqsnl*zcor
        zdqsdt = ra2*(tmelt-ra4)*zqsnl*zcor/((ztnew5-ra4)*(ztnew5-ra4))
        zdqsdt_ad = zdqsdt_ad-zrain_ad*((zqnew5-zqsnl)*zlcp/(1.+zlcp*zdqsdt)/(1.+zlcp*zdqsdt))
        zlcp_ad = zlcp_ad-zrain_ad*((zqnew5-zqsnl)*zdqsdt/(1.+zlcp*zdqsdt)/(1.+zlcp*zdqsdt))
        zqnew5_ad = zqnew5_ad+zrain_ad/(1.+zlcp*zdqsdt)
        zqsnl_ad = zqsnl_ad-zrain_ad/(1.+zlcp*zdqsdt)
        zrain_ad = 0.
        zqsnl = rdbrv*ra1*exp(ra2*(ztnew5-tmelt)/(ztnew5-ra4))/(dp(jhor)*sigma(jlev))
        zqsnl = amin1(zqsnl,rdbrv)
        zcor = 1./(1.-(1./rdbrv-1.)*zqsnl)
        zqsnl = zqsnl*zcor
        zcor_ad = zcor_ad+zdqsdt_ad*(ra2*(tmelt-ra4)*zqsnl/((ztnew5-ra4)*(ztnew5-ra4)))
        zqsnl_ad = zqsnl_ad+zdqsdt_ad*(ra2*(tmelt-ra4)*zcor/((ztnew5-ra4)*(ztnew5-ra4)))
        ztnew5_ad = ztnew5_ad-zdqsdt_ad*(2*(ra2*(tmelt-ra4)*zqsnl*zcor)*(ztnew5-ra4)/((ztnew5-ra4)*(ztnew5-ra4))/((ztnew5-ra4)*&
&(ztnew5-ra4)))
        zdqsdt_ad = 0.
        zqsnl = rdbrv*ra1*exp(ra2*(ztnew5-tmelt)/(ztnew5-ra4))/(dp(jhor)*sigma(jlev))
        zqsnl = amin1(zqsnl,rdbrv)
        zcor = 1./(1.-(1./rdbrv-1.)*zqsnl)
        zcor_ad = zcor_ad+zqsnl_ad*zqsnl
        zqsnl_ad = zqsnl_ad*zcor
        zqsnl = rdbrv*ra1*exp(ra2*(ztnew5-tmelt)/(ztnew5-ra4))/(dp(jhor)*sigma(jlev))
        zqsnl = amin1(zqsnl,rdbrv)
        zqsnl_ad = zqsnl_ad-zcor_ad*(1.*(1-1./rdbrv)/(1.-(1./rdbrv-1.)*zqsnl)/(1.-(1./rdbrv-1.)*zqsnl))
        zcor_ad = 0.
        zqsnl = rdbrv*ra1*exp(ra2*(ztnew5-tmelt)/(ztnew5-ra4))/(dp(jhor)*sigma(jlev))
        zqsnl_ad = zqsnl_ad*(0.5+sign(0.5,rdbrv-zqsnl))
        zqsnll = ra2*(ztnew5-tmelt)/(ztnew5-ra4)
        dp_ad(jhor) = dp_ad(jhor)-zqsnl_ad*(rdbrv*ra1*sigma(jlev)*exp(zqsnll)/(dp(jhor)*sigma(jlev))/(dp(jhor)*sigma(jlev)))
        ztnew5_ad = ztnew5_ad+zqsnl_ad*(rdbrv*ra1*exp(zqsnll)/(dp(jhor)*sigma(jlev)))*((ra2-ra2*(ztnew5-tmelt)/(ztnew5-ra4))/&
&(ztnew5-ra4))
        zqsnl_ad = 0.
        zqnew4_ad = zqnew4_ad+zqnew5_ad
        zrain_ad = zrain_ad-zqnew5_ad
        zqnew5_ad = 0.
        zqsnl = rdbrv*ra1*exp(ra2*(ztnew4-tmelt)/(ztnew4-ra4))/(dp(jhor)*sigma(jlev))
        zqsnl = amin1(zqsnl,rdbrv)
        zcor = 1./(1.-(1./rdbrv-1.)*zqsnl)
        zqsnl = zqsnl*zcor
        if (ztnew4 < tmelt) then
          zlcp = als/(acpd*(1.+adv*zqnew4))
        else
          zlcp = alv/(acpd*(1.+adv*zqnew4))
        endif
        zdqsdt = ra2*(tmelt-ra4)*zqsnl*zcor/((ztnew4-ra4)*(ztnew4-ra4))
        zrain = (zqnew4-zqsnl)/(1.+zlcp*zdqsdt)
        zlcp_ad = zlcp_ad+ztnew5_ad*zrain
        zrain_ad = zrain_ad+ztnew5_ad*zlcp
        ztnew4_ad = ztnew4_ad+ztnew5_ad
        ztnew5_ad = 0.
        zqsnl = rdbrv*ra1*exp(ra2*(ztnew4-tmelt)/(ztnew4-ra4))/(dp(jhor)*sigma(jlev))
        zqsnl = amin1(zqsnl,rdbrv)
        zcor = 1./(1.-(1./rdbrv-1.)*zqsnl)
        zqsnl = zqsnl*zcor
        if (ztnew4 < tmelt) then
          zlcp = als/(acpd*(1.+adv*zqnew4))
        else
          zlcp = alv/(acpd*(1.+adv*zqnew4))
        endif
        zdqsdt = ra2*(tmelt-ra4)*zqsnl*zcor/((ztnew4-ra4)*(ztnew4-ra4))
        zdqsdt_ad = zdqsdt_ad-zrain_ad*((zqnew4-zqsnl)*zlcp/(1.+zlcp*zdqsdt)/(1.+zlcp*zdqsdt))
        zlcp_ad = zlcp_ad-zrain_ad*((zqnew4-zqsnl)*zdqsdt/(1.+zlcp*zdqsdt)/(1.+zlcp*zdqsdt))
        zqnew4_ad = zqnew4_ad+zrain_ad/(1.+zlcp*zdqsdt)
        zqsnl_ad = zqsnl_ad-zrain_ad/(1.+zlcp*zdqsdt)
        zrain_ad = 0.
        zqsnl = rdbrv*ra1*exp(ra2*(ztnew4-tmelt)/(ztnew4-ra4))/(dp(jhor)*sigma(jlev))
        zqsnl = amin1(zqsnl,rdbrv)
        zcor = 1./(1.-(1./rdbrv-1.)*zqsnl)
        zqsnl = zqsnl*zcor
        zcor_ad = zcor_ad+zdqsdt_ad*(ra2*(tmelt-ra4)*zqsnl/((ztnew4-ra4)*(ztnew4-ra4)))
        zqsnl_ad = zqsnl_ad+zdqsdt_ad*(ra2*(tmelt-ra4)*zcor/((ztnew4-ra4)*(ztnew4-ra4)))
        ztnew4_ad = ztnew4_ad-zdqsdt_ad*(2*(ra2*(tmelt-ra4)*zqsnl*zcor)*(ztnew4-ra4)/((ztnew4-ra4)*(ztnew4-ra4))/((ztnew4-ra4)*&
&(ztnew4-ra4)))
        zdqsdt_ad = 0.
        if (ztnew4 < tmelt) then
          zqnew4_ad = zqnew4_ad-zlcp_ad*(als*acpd*adv/(acpd*(1.+adv*zqnew4))/(acpd*(1.+adv*zqnew4)))
          zlcp_ad = 0.
        else
          zqnew4_ad = zqnew4_ad-zlcp_ad*(alv*acpd*adv/(acpd*(1.+adv*zqnew4))/(acpd*(1.+adv*zqnew4)))
          zlcp_ad = 0.
        endif
      endif
      zqsnl = rdbrv*ra1*exp(ra2*(ztnew4-tmelt)/(ztnew4-ra4))/(dp(jhor)*sigma(jlev))
      zqsnl = amin1(zqsnl,rdbrv)
      zcor = 1./(1.-(1./rdbrv-1.)*zqsnl)
      zcor_ad = zcor_ad+zqsnl_ad*zqsnl
      zqsnl_ad = zqsnl_ad*zcor
      zqsnl = rdbrv*ra1*exp(ra2*(ztnew4-tmelt)/(ztnew4-ra4))/(dp(jhor)*sigma(jlev))
      zqsnl = amin1(zqsnl,rdbrv)
      zqsnl_ad = zqsnl_ad-zcor_ad*(1.*(1-1./rdbrv)/(1.-(1./rdbrv-1.)*zqsnl)/(1.-(1./rdbrv-1.)*zqsnl))
      zcor_ad = 0.
      zqsnl = rdbrv*ra1*exp(ra2*(ztnew4-tmelt)/(ztnew4-ra4))/(dp(jhor)*sigma(jlev))
      zqsnl_ad = zqsnl_ad*(0.5+sign(0.5,rdbrv-zqsnl))
      zqsnlm = ra2*(ztnew4-tmelt)/(ztnew4-ra4)
      dp_ad(jhor) = dp_ad(jhor)-zqsnl_ad*(rdbrv*ra1*sigma(jlev)*exp(zqsnlm)/(dp(jhor)*sigma(jlev))/(dp(jhor)*sigma(jlev)))
      ztnew4_ad = ztnew4_ad+zqsnl_ad*(rdbrv*ra1*exp(zqsnlm)/(dp(jhor)*sigma(jlev)))*((ra2-ra2*(ztnew4-tmelt)/(ztnew4-ra4))/(ztnew4-&
&ra4))
      zqsnl_ad = 0.
      zqe_ad(jhor,jlep) = zqe_ad(jhor,jlep)+zqnew4_ad
      zqnew4_ad = 0.
      zte_ad(jhor,jlep) = zte_ad(jhor,jlep)+ztnew4_ad*zfac
      ztnew4_ad = 0.
    endif
  end do
end do
dtdt = dtdth(:,:)
zte(:,:) = dt(:,1:nlev)+dtdt(:,1:nlev)*deltsec2
if (ncsurf == 1) then
  zfac = sigma(nlev)**akap
  do jhor = nhor, 1, -1
!$taf INCOMPLETE zqp_ad,ztp_ad
    ztnew1 = dt(jhor,nlep)*zfac
!$taf INCOMPLETE zqp_ad,ztp_ad
    if (zdqtot(jhor,nlev) > 0. .and. ztnew1 > zte(jhor,nlev)) then
!$taf INCOMPLETE zqp_ad,ztp_ad
      zqsnl = rdbrv*ra1*exp(ra2*(zte(jhor,nlev)-tmelt)/(zte(jhor,nlev)-ra4))/(dp(jhor)*sigma(nlev))
      zqsnl = amin1(zqsnl,rdbrv)
      zqsnl = zqsnl/(1.-(1./rdbrv-1.)*zqsnl)
      zqnew1 = dq(jhor,nlep)*amin1(1.,zqe(jhor,nlev)/zqsnl)
      zqsnl = rdbrv*ra1*exp(ra2*(ztnew1-tmelt)/(ztnew1-ra4))/(dp(jhor)*sigma(nlev))
      zqsnl = amin1(zqsnl,rdbrv)
      zcor = 1./(1.-(1./rdbrv-1.)*zqsnl)
      zqsnl = zqsnl*zcor
!$taf INCOMPLETE zqp_ad,ztp_ad
      if (zqsnl < zqnew1) then
!$taf INCOMPLETE zdtdt,ztp
        if (ztnew1 < tmelt) then
          zlcp = als/(acpd*(1.+adv*zqnew1))
        else
          zlcp = alv/(acpd*(1.+adv*zqnew1))
        endif
        zdqsdt = ra2*(tmelt-ra4)*zqsnl*zcor/((ztnew1-ra4)*(ztnew1-ra4))
        zrain = (zqnew1-zqsnl)/(1.+zlcp*zdqsdt)
        ztnew2 = ztnew1+zlcp*zrain
        zqnew2 = zqnew1-zrain
        zqsnl = rdbrv*ra1*exp(ra2*(ztnew2-tmelt)/(ztnew2-ra4))/(dp(jhor)*sigma(nlev))
        zqsnl = amin1(zqsnl,rdbrv)
        zcor = 1./(1.-(1./rdbrv-1.)*zqsnl)
        zqsnl = zqsnl*zcor
        zdqsdt = ra2*(tmelt-ra4)*zqsnl*zcor/((ztnew2-ra4)*(ztnew2-ra4))
        zrain = (zqnew2-zqsnl)/(1.+zlcp*zdqsdt)
        ztnew3 = ztnew2+zlcp*zrain
        ztp(jhor) = ztnew3
        zqsa = rdbrv*ra1*exp(ra2*(zte(jhor,nlev)-tmelt)/(zte(jhor,nlev)-ra4))/(dp(jhor)*sigma(nlev))
        zqsa = amin1(zqsa,rdbrv)
        zqsa = zqsa/(1.-(1./rdbrv-1.)*zqsa)
        zdtdt(jhor,nlev) = ztp(jhor)-zte(jhor,nlev)
        zdqtot_ad(jhor,nlev) = zdqtot_ad(jhor,nlev)+zi_ad(jhor)*dsigma(nlev)*zale(jhor,nlev)
        zi_ad(jhor) = 0.
        if (kbeta > 0) then
          zbetah_ag = 0._8
          zbetah_ag = zbeta_ad(jhor)*dsigma(nlev)*(0.5-sign(0.5,zqe(jhor,nlev)/zqsa-1.))
          zqe_ad(jhor,nlev) = zqe_ad(jhor,nlev)+zbetah_ag/zqsa
          zqsa_ad = zqsa_ad-zbetah_ag*(zqe(jhor,nlev)/zqsa/zqsa)
          zbeta_ad(jhor) = 0.
        endif
        zdqdt_ad(jhor,nlev) = zdqdt_ad(jhor,nlev)+zpq_ad(jhor)*dsigma(nlev)*zale(jhor,nlev)
        zpq_ad(jhor) = 0.
        zacpe_ad(jhor,nlev) = zacpe_ad(jhor,nlev)+zpt_ad(jhor)*zdtdt(jhor,nlev)*dsigma(nlev)
        zdtdt_ad(jhor,nlev) = zdtdt_ad(jhor,nlev)+zpt_ad(jhor)*dsigma(nlev)*zacpe(jhor,nlev)
        zpt_ad(jhor) = 0.
        zte_ad(jhor,nlev) = zte_ad(jhor,nlev)-zdtdt_ad(jhor,nlev)
        ztp_ad(jhor) = ztp_ad(jhor)+zdtdt_ad(jhor,nlev)
        zdtdt_ad(jhor,nlev) = 0.
        zqe_ad(jhor,nlev) = zqe_ad(jhor,nlev)-zdqdt_ad(jhor,nlev)*(0.5+sign(0.5,zqsa-zqe(jhor,nlev)-0.))
        zqsa_ad = zqsa_ad+zdqdt_ad(jhor,nlev)*(0.5+sign(0.5,zqsa-zqe(jhor,nlev)-0.))
        zdqdt_ad(jhor,nlev) = 0.
        zqsa = rdbrv*ra1*exp(ra2*(zte(jhor,nlev)-tmelt)/(zte(jhor,nlev)-ra4))/(dp(jhor)*sigma(nlev))
        zqsa = amin1(zqsa,rdbrv)
        zqsa_ad = zqsa_ad*((1-zqsa*(1-1./rdbrv)/(1.-(1./rdbrv-1.)*zqsa))/(1.-(1./rdbrv-1.)*zqsa))
        zqsa = rdbrv*ra1*exp(ra2*(zte(jhor,nlev)-tmelt)/(zte(jhor,nlev)-ra4))/(dp(jhor)*sigma(nlev))
        zqsa_ad = zqsa_ad*(0.5+sign(0.5,rdbrv-zqsa))
        zqsaj = ra2*(zte(jhor,nlev)-tmelt)/(zte(jhor,nlev)-ra4)
        dp_ad(jhor) = dp_ad(jhor)-zqsa_ad*(rdbrv*ra1*sigma(nlev)*exp(zqsaj)/(dp(jhor)*sigma(nlev))/(dp(jhor)*sigma(nlev)))
        zte_ad(jhor,nlev) = zte_ad(jhor,nlev)+zqsa_ad*(rdbrv*ra1*exp(zqsaj)/(dp(jhor)*sigma(nlev)))*((ra2-ra2*(zte(jhor,nlev)-&
&tmelt)/(zte(jhor,nlev)-ra4))/(zte(jhor,nlev)-ra4))
        zqsa_ad = 0.
        zqnew3_ad = zqnew3_ad+zqp_ad(jhor)
        zqp_ad(jhor) = 0.
        ztnew3_ad = ztnew3_ad+ztp_ad(jhor)
        ztp_ad(jhor) = 0.
        zqnew2_ad = zqnew2_ad+zqnew3_ad
        zrain_ad = zrain_ad-zqnew3_ad
        zqnew3_ad = 0.
        zlcp_ad = zlcp_ad+ztnew3_ad*zrain
        zrain_ad = zrain_ad+ztnew3_ad*zlcp
        ztnew2_ad = ztnew2_ad+ztnew3_ad
        ztnew3_ad = 0.
        zdqsdt_ad = zdqsdt_ad-zrain_ad*((zqnew2-zqsnl)*zlcp/(1.+zlcp*zdqsdt)/(1.+zlcp*zdqsdt))
        zlcp_ad = zlcp_ad-zrain_ad*((zqnew2-zqsnl)*zdqsdt/(1.+zlcp*zdqsdt)/(1.+zlcp*zdqsdt))
        zqnew2_ad = zqnew2_ad+zrain_ad/(1.+zlcp*zdqsdt)
        zqsnl_ad = zqsnl_ad-zrain_ad/(1.+zlcp*zdqsdt)
        zrain_ad = 0.
        zcor_ad = zcor_ad+zdqsdt_ad*(ra2*(tmelt-ra4)*zqsnl/((ztnew2-ra4)*(ztnew2-ra4)))
        zqsnl_ad = zqsnl_ad+zdqsdt_ad*(ra2*(tmelt-ra4)*zcor/((ztnew2-ra4)*(ztnew2-ra4)))
        ztnew2_ad = ztnew2_ad-zdqsdt_ad*(2*(ra2*(tmelt-ra4)*zqsnl*zcor)*(ztnew2-ra4)/((ztnew2-ra4)*(ztnew2-ra4))/((ztnew2-ra4)*&
&(ztnew2-ra4)))
        zdqsdt_ad = 0.
        zqsnl = rdbrv*ra1*exp(ra2*(ztnew2-tmelt)/(ztnew2-ra4))/(dp(jhor)*sigma(nlev))
        zqsnl = amin1(zqsnl,rdbrv)
        zcor_ad = zcor_ad+zqsnl_ad*zqsnl
        zqsnl_ad = zqsnl_ad*zcor
        zqsnl = rdbrv*ra1*exp(ra2*(ztnew2-tmelt)/(ztnew2-ra4))/(dp(jhor)*sigma(nlev))
        zqsnl = amin1(zqsnl,rdbrv)
        zqsnl_ad = zqsnl_ad-zcor_ad*(1.*(1-1./rdbrv)/(1.-(1./rdbrv-1.)*zqsnl)/(1.-(1./rdbrv-1.)*zqsnl))
        zcor_ad = 0.
        zqsnl = rdbrv*ra1*exp(ra2*(ztnew2-tmelt)/(ztnew2-ra4))/(dp(jhor)*sigma(nlev))
        zqsnl_ad = zqsnl_ad*(0.5+sign(0.5,rdbrv-zqsnl))
        zqsnln = ra2*(ztnew2-tmelt)/(ztnew2-ra4)
        dp_ad(jhor) = dp_ad(jhor)-zqsnl_ad*(rdbrv*ra1*sigma(nlev)*exp(zqsnln)/(dp(jhor)*sigma(nlev))/(dp(jhor)*sigma(nlev)))
        ztnew2_ad = ztnew2_ad+zqsnl_ad*(rdbrv*ra1*exp(zqsnln)/(dp(jhor)*sigma(nlev)))*((ra2-ra2*(ztnew2-tmelt)/(ztnew2-ra4))/&
&(ztnew2-ra4))
        zqsnl_ad = 0.
        zqnew1_ad = zqnew1_ad+zqnew2_ad
        zrain_ad = zrain_ad-zqnew2_ad
        zqnew2_ad = 0.
        zqsnl = rdbrv*ra1*exp(ra2*(ztnew1-tmelt)/(ztnew1-ra4))/(dp(jhor)*sigma(nlev))
        zqsnl = amin1(zqsnl,rdbrv)
        zcor = 1./(1.-(1./rdbrv-1.)*zqsnl)
        zqsnl = zqsnl*zcor
        zdqsdt = ra2*(tmelt-ra4)*zqsnl*zcor/((ztnew1-ra4)*(ztnew1-ra4))
        zrain = (zqnew1-zqsnl)/(1.+zlcp*zdqsdt)
        zlcp_ad = zlcp_ad+ztnew2_ad*zrain
        zrain_ad = zrain_ad+ztnew2_ad*zlcp
        ztnew1_ad = ztnew1_ad+ztnew2_ad
        ztnew2_ad = 0.
        zqsnl = rdbrv*ra1*exp(ra2*(ztnew1-tmelt)/(ztnew1-ra4))/(dp(jhor)*sigma(nlev))
        zqsnl = amin1(zqsnl,rdbrv)
        zcor = 1./(1.-(1./rdbrv-1.)*zqsnl)
        zqsnl = zqsnl*zcor
        zdqsdt = ra2*(tmelt-ra4)*zqsnl*zcor/((ztnew1-ra4)*(ztnew1-ra4))
        zdqsdt_ad = zdqsdt_ad-zrain_ad*((zqnew1-zqsnl)*zlcp/(1.+zlcp*zdqsdt)/(1.+zlcp*zdqsdt))
        zlcp_ad = zlcp_ad-zrain_ad*((zqnew1-zqsnl)*zdqsdt/(1.+zlcp*zdqsdt)/(1.+zlcp*zdqsdt))
        zqnew1_ad = zqnew1_ad+zrain_ad/(1.+zlcp*zdqsdt)
        zqsnl_ad = zqsnl_ad-zrain_ad/(1.+zlcp*zdqsdt)
        zrain_ad = 0.
        zqsnl = rdbrv*ra1*exp(ra2*(ztnew1-tmelt)/(ztnew1-ra4))/(dp(jhor)*sigma(nlev))
        zqsnl = amin1(zqsnl,rdbrv)
        zcor = 1./(1.-(1./rdbrv-1.)*zqsnl)
        zqsnl = zqsnl*zcor
        zcor_ad = zcor_ad+zdqsdt_ad*(ra2*(tmelt-ra4)*zqsnl/((ztnew1-ra4)*(ztnew1-ra4)))
        zqsnl_ad = zqsnl_ad+zdqsdt_ad*(ra2*(tmelt-ra4)*zcor/((ztnew1-ra4)*(ztnew1-ra4)))
        ztnew1_ad = ztnew1_ad-zdqsdt_ad*(2*(ra2*(tmelt-ra4)*zqsnl*zcor)*(ztnew1-ra4)/((ztnew1-ra4)*(ztnew1-ra4))/((ztnew1-ra4)*&
&(ztnew1-ra4)))
        zdqsdt_ad = 0.
        if (ztnew1 < tmelt) then
          zqnew1_ad = zqnew1_ad-zlcp_ad*(als*acpd*adv/(acpd*(1.+adv*zqnew1))/(acpd*(1.+adv*zqnew1)))
          zlcp_ad = 0.
        else
          zqnew1_ad = zqnew1_ad-zlcp_ad*(alv*acpd*adv/(acpd*(1.+adv*zqnew1))/(acpd*(1.+adv*zqnew1)))
          zlcp_ad = 0.
        endif
      endif
      zqsnl = rdbrv*ra1*exp(ra2*(ztnew1-tmelt)/(ztnew1-ra4))/(dp(jhor)*sigma(nlev))
      zqsnl = amin1(zqsnl,rdbrv)
      zcor = 1./(1.-(1./rdbrv-1.)*zqsnl)
      zcor_ad = zcor_ad+zqsnl_ad*zqsnl
      zqsnl_ad = zqsnl_ad*zcor
      zqsnl = rdbrv*ra1*exp(ra2*(ztnew1-tmelt)/(ztnew1-ra4))/(dp(jhor)*sigma(nlev))
      zqsnl = amin1(zqsnl,rdbrv)
      zqsnl_ad = zqsnl_ad-zcor_ad*(1.*(1-1./rdbrv)/(1.-(1./rdbrv-1.)*zqsnl)/(1.-(1./rdbrv-1.)*zqsnl))
      zcor_ad = 0.
      zqsnl = rdbrv*ra1*exp(ra2*(ztnew1-tmelt)/(ztnew1-ra4))/(dp(jhor)*sigma(nlev))
      zqsnl_ad = zqsnl_ad*(0.5+sign(0.5,rdbrv-zqsnl))
      zqsnlo = ra2*(ztnew1-tmelt)/(ztnew1-ra4)
      dp_ad(jhor) = dp_ad(jhor)-zqsnl_ad*(rdbrv*ra1*sigma(nlev)*exp(zqsnlo)/(dp(jhor)*sigma(nlev))/(dp(jhor)*sigma(nlev)))
      ztnew1_ad = ztnew1_ad+zqsnl_ad*(rdbrv*ra1*exp(zqsnlo)/(dp(jhor)*sigma(nlev)))*((ra2-ra2*(ztnew1-tmelt)/(ztnew1-ra4))/(ztnew1-&
&ra4))
      zqsnl_ad = 0.
      zqsnl = rdbrv*ra1*exp(ra2*(zte(jhor,nlev)-tmelt)/(zte(jhor,nlev)-ra4))/(dp(jhor)*sigma(nlev))
      zqsnl = amin1(zqsnl,rdbrv)
      zqsnl = zqsnl/(1.-(1./rdbrv-1.)*zqsnl)
      zqnew1h = zqe(jhor,nlev)/zqsnl
      zqnew1h_ad = 0._8
      dq_ad(jhor,nlep) = dq_ad(jhor,nlep)+zqnew1_ad*amin1(1.,zqnew1h)
