    where (zq(:) < zqsat(:) .and. zprsl(:) > zeps)
      zlcpe(:) = als/(acpd*(1.+adv*dq(:,jlev)))
      zdqdt(:) = amin1(gamma*(zqsat(:)-zq(:))*dsigma(jlev)/deltsec2/(1.0+zlcpe(:)*ra2*(tmelt-ra4)*zqsat(:)*zcor(:)/(zt(:)-ra4)**2),&
&zprsl(:))
      zprsl(:) = zprsl(:)-zdqdt(:)
      zdqdt(:) = zdqdt(:)/dsigma(jlev)
    end where
    where (zq(:) < zqsat(:) .and. zprsc(:) > zeps)
      zlcpe(:) = als/(acpd*(1.+adv*dq(:,jlev)))
      zdqdt(:) = amin1(gamma*(zqsat(:)-zq(:))*dsigma(jlev)/deltsec2/(1.0+zlcpe(:)*ra2*(tmelt-ra4)*zqsat(:)*zcor(:)/(zt(:)-ra4)**2),&
&zprsc(:))
      zprsc(:) = zprsc(:)-zdqdt(:)
      zdqdt(:) = zdqdt(:)/dsigma(jlev)
    end where
  endif
end do

!----------------------------------------------
! ADJOINT COMPUTATIONS
!----------------------------------------------
!$taf INCOMPLETE dqdt_ad,dtdt_ad
zdtdt_ad(:,1:nlev) = zdtdt_ad(:,1:nlev)+dtdt_ad(:,1:nlev)
!$taf INCOMPLETE dqdt_ad,dtdt_ad
zdqdtl_ad(:,1:nlev) = zdqdtl_ad(:,1:nlev)+dqdt_ad(:,1:nlev)
zdqdts_ad(:,1:nlev) = zdqdts_ad(:,1:nlev)+dqdt_ad(:,1:nlev)
dp_ad(:) = dp_ad(:)+dprs_ad(:)*((zprsc(:)+zprsl(:))/ga/1000.)
zprsc_ad(:) = zprsc_ad(:)+dprs_ad(:)*(dp(:)/ga/1000.)
zprsl_ad(:) = zprsl_ad(:)+dprs_ad(:)*(dp(:)/ga/1000.)
dprs_ad(:) = 0.
dp_ad(:) = dp_ad(:)+dprl_ad(:)*((zprl(:)+zprsl(:))/ga/1000.)
zprl_ad(:) = zprl_ad(:)+dprl_ad(:)*(dp(:)/ga/1000.)
zprsl_ad(:) = zprsl_ad(:)+dprl_ad(:)*(dp(:)/ga/1000.)
dprl_ad(:) = 0.
dp_ad(:) = dp_ad(:)+dprc_ad(:)*((zprc(:)+zprsc(:))/ga/1000.)
zprc_ad(:) = zprc_ad(:)+dprc_ad(:)*(dp(:)/ga/1000.)
zprsc_ad(:) = zprsc_ad(:)+dprc_ad(:)*(dp(:)/ga/1000.)
dprc_ad(:) = 0.
do jlev = nlev, 1, -1
  zprsl = mkrain_zprsl_4h(:,jlev)
  zprsc = mkrain_zprsc_3h(:,jlev)
  zprl = mkrain_zprl_2h(:,jlev)
  zprc = mkrain_zprc_1h(:,jlev)
  zprc(:) = zprc(:)+dprcl(:,jlev)-dprscl(:,jlev)
  zprl(:) = zprl(:)+dprll(:,jlev)-dprsll(:,jlev)
  zprsc(:) = zprsc(:)+dprscl(:,jlev)
  zprsl(:) = zprsl(:)+dprsll(:,jlev)
  where (zprsc(:)+zprsl(:) > 0. .and. dt(:,jlev) > tmelt)
    zprc(:) = zprsc(:)+zprc(:)
    zprl(:) = zprsl(:)+zprl(:)
    zprsc(:) = 0.
    zprsl(:) = 0.
  elsewhere (zprc(:)+zprl(:) > 0. .and. dt(:,jlev) <= tmelt)
    zprsc(:) = zprc(:)+zprsc(:)
    zprsl(:) = zprl(:)+zprsl(:)
    zprc(:) = 0.
    zprl(:) = 0.
  end where
  if (jlev == nlev) then
    where (zprsc(:)+zprsl(:) > 0. .and. dt(:,nlep) > tmelt)
      zprc(:) = zprsc(:)+zprc(:)
      zprl(:) = zprsl(:)+zprl(:)
      zprsc(:) = 0.
      zprsl(:) = 0.
    elsewhere (zprc(:)+zprl(:) > 0. .and. dt(:,nlep) <= tmelt)
      zprsc(:) = zprc(:)+zprsc(:)
      zprsl(:) = zprl(:)+zprsl(:)
      zprc(:) = 0.
      zprl(:) = 0.
    end where
  endif
  if (nevapprec == 1) then
    zq(:) = dq(:,jlev)+dqdt(:,jlev)*deltsec2
    zt(:) = dt(:,jlev)+dtdt(:,jlev)*deltsec2
    zqsat = mkrain_zqsat_5h(:,jlev)
    zqsat(:) = amin1(zqsat(:),rdbrv)
    zcor(:) = 1./(1.-(1./rdbrv-1.)*zqsat(:))
    zqsat(:) = zqsat(:)*zcor(:)
    where (zqsat(:) < 0.0)
      zqsat(:) = 0.0
    end where
    whcondo = zq(:) < zqsat(:) .and. zprsc(:) > zeps
    where (whcondo)
      zlcpe(:) = als/(acpd*(1.+adv*dq(:,jlev)))
      zdqdt(:) = amin1(gamma*(zqsat(:)-zq(:))*dsigma(jlev)/deltsec2/(1.0+zlcpe(:)*ra2*(tmelt-ra4)*zqsat(:)*zcor(:)/(zt(:)-ra4)**2),&
&zprsc(:))
      zdqdt(:) = zdqdt(:)/dsigma(jlev)
      zdqdt_ad(:) = zdqdt_ad(:)+zdqdts_ad(:,jlev)
      zdqdt_ad(:) = zdqdt_ad(:)-zdtdt_ad(:,jlev)*zlcpe(:)
      zlcpe_ad(:) = zlcpe_ad(:)-zdtdt_ad(:,jlev)*zdqdt(:)
      zdqdt_ad(:) = zdqdt_ad(:)/dsigma(jlev)
      zdqdt_ad(:) = zdqdt_ad(:)-zprsc_ad(:)
      zcor_ad(:) = zcor_ad(:)-zdqdt_ad(:)*(0.5+sign(0.5,zprsc(:)-gamma*(zqsat(:)-zq(:))*dsigma(jlev)/deltsec2/(1.0+zlcpe(:)*ra2*&
&(tmelt-ra4)*zqsat(:)*zcor(:)/(zt(:)-ra4)**2)))*(gamma*(zqsat(:)-zq(:))*dsigma(jlev)/deltsec2*(zlcpe(:)*ra2*(tmelt-ra4)*&
&zqsat(:)/(zt(:)-ra4)**2)/(1.0+zlcpe(:)*ra2*(tmelt-ra4)*zqsat(:)*zcor(:)/(zt(:)-ra4)**2)/(1.0+zlcpe(:)*ra2*(tmelt-ra4)*&
&zqsat(:)*zcor(:)/(zt(:)-ra4)**2))
      zlcpe_ad(:) = zlcpe_ad(:)-zdqdt_ad(:)*(0.5+sign(0.5,zprsc(:)-gamma*(zqsat(:)-zq(:))*dsigma(jlev)/deltsec2/(1.0+zlcpe(:)*ra2*&
&(tmelt-ra4)*zqsat(:)*zcor(:)/(zt(:)-ra4)**2)))*(gamma*(zqsat(:)-zq(:))*dsigma(jlev)/deltsec2*(ra2*(tmelt-ra4)*zqsat(:)*&
&zcor(:)/(zt(:)-ra4)**2)/(1.0+zlcpe(:)*ra2*(tmelt-ra4)*zqsat(:)*zcor(:)/(zt(:)-ra4)**2)/(1.0+zlcpe(:)*ra2*(tmelt-ra4)*zqsat(:&
&)*zcor(:)/(zt(:)-ra4)**2))
      zprsc_ad(:) = zprsc_ad(:)+zdqdt_ad(:)*(0.5-sign(0.5,zprsc(:)-gamma*(zqsat(:)-zq(:))*dsigma(jlev)/deltsec2/(1.0+zlcpe(:)*ra2*&
&(tmelt-ra4)*zqsat(:)*zcor(:)/(zt(:)-ra4)**2)))
      zq_ad(:) = zq_ad(:)-zdqdt_ad(:)*(0.5+sign(0.5,zprsc(:)-gamma*(zqsat(:)-zq(:))*dsigma(jlev)/deltsec2/(1.0+zlcpe(:)*ra2*(tmelt-&
&ra4)*zqsat(:)*zcor(:)/(zt(:)-ra4)**2)))*(gamma*dsigma(jlev)/deltsec2/(1.0+zlcpe(:)*ra2*(tmelt-ra4)*zqsat(:)*zcor(:)/(zt(:)-&
&ra4)**2))
      zqsat_ad(:) = zqsat_ad(:)+zdqdt_ad(:)*(0.5+sign(0.5,zprsc(:)-gamma*(zqsat(:)-zq(:))*dsigma(jlev)/deltsec2/(1.0+zlcpe(:)*ra2*&
&(tmelt-ra4)*zqsat(:)*zcor(:)/(zt(:)-ra4)**2)))*((gamma*dsigma(jlev)/deltsec2-gamma*(zqsat(:)-zq(:))*dsigma(jlev)/deltsec2*&
&(zlcpe(:)*ra2*(tmelt-ra4)*zcor(:)/(zt(:)-ra4)**2)/(1.0+zlcpe(:)*ra2*(tmelt-ra4)*zqsat(:)*zcor(:)/(zt(:)-ra4)**2))/(1.0+&
&zlcpe(:)*ra2*(tmelt-ra4)*zqsat(:)*zcor(:)/(zt(:)-ra4)**2))
      zt_ad(:) = zt_ad(:)+zdqdt_ad(:)*(0.5+sign(0.5,zprsc(:)-gamma*(zqsat(:)-zq(:))*dsigma(jlev)/deltsec2/(1.0+zlcpe(:)*ra2*(tmelt-&
&ra4)*zqsat(:)*zcor(:)/(zt(:)-ra4)**2)))*(gamma*(zqsat(:)-zq(:))*dsigma(jlev)/deltsec2*(2*(zlcpe(:)*ra2*(tmelt-ra4)*zqsat(:)*&
&zcor(:))*(zt(:)-ra4)/(zt(:)-ra4)**2/(zt(:)-ra4)**2)/(1.0+zlcpe(:)*ra2*(tmelt-ra4)*zqsat(:)*zcor(:)/(zt(:)-ra4)**2)/(1.0+&
&zlcpe(:)*ra2*(tmelt-ra4)*zqsat(:)*zcor(:)/(zt(:)-ra4)**2))
      zdqdt_ad(:) = 0.
      dq_ad(:,jlev) = dq_ad(:,jlev)-zlcpe_ad(:)*(als*acpd*adv/(acpd*(1.+adv*dq(:,jlev)))/(acpd*(1.+adv*dq(:,jlev))))
      zlcpe_ad(:) = 0.
    end where
    whcondp = zq(:) < zqsat(:) .and. zprsl(:) > zeps
    where (whcondp)
      zlcpe(:) = als/(acpd*(1.+adv*dq(:,jlev)))
      zdqdt(:) = amin1(gamma*(zqsat(:)-zq(:))*dsigma(jlev)/deltsec2/(1.0+zlcpe(:)*ra2*(tmelt-ra4)*zqsat(:)*zcor(:)/(zt(:)-ra4)**2),&
&zprsl(:))
      zdqdt(:) = zdqdt(:)/dsigma(jlev)
      zdqdt_ad(:) = zdqdt_ad(:)+zdqdts_ad(:,jlev)
      zdqdt_ad(:) = zdqdt_ad(:)-zdtdt_ad(:,jlev)*zlcpe(:)
      zlcpe_ad(:) = zlcpe_ad(:)-zdtdt_ad(:,jlev)*zdqdt(:)
      zdqdt_ad(:) = zdqdt_ad(:)/dsigma(jlev)
      zdqdt_ad(:) = zdqdt_ad(:)-zprsl_ad(:)
      zcor_ad(:) = zcor_ad(:)-zdqdt_ad(:)*(0.5+sign(0.5,zprsl(:)-gamma*(zqsat(:)-zq(:))*dsigma(jlev)/deltsec2/(1.0+zlcpe(:)*ra2*&
&(tmelt-ra4)*zqsat(:)*zcor(:)/(zt(:)-ra4)**2)))*(gamma*(zqsat(:)-zq(:))*dsigma(jlev)/deltsec2*(zlcpe(:)*ra2*(tmelt-ra4)*&
&zqsat(:)/(zt(:)-ra4)**2)/(1.0+zlcpe(:)*ra2*(tmelt-ra4)*zqsat(:)*zcor(:)/(zt(:)-ra4)**2)/(1.0+zlcpe(:)*ra2*(tmelt-ra4)*&
&zqsat(:)*zcor(:)/(zt(:)-ra4)**2))
      zlcpe_ad(:) = zlcpe_ad(:)-zdqdt_ad(:)*(0.5+sign(0.5,zprsl(:)-gamma*(zqsat(:)-zq(:))*dsigma(jlev)/deltsec2/(1.0+zlcpe(:)*ra2*&
&(tmelt-ra4)*zqsat(:)*zcor(:)/(zt(:)-ra4)**2)))*(gamma*(zqsat(:)-zq(:))*dsigma(jlev)/deltsec2*(ra2*(tmelt-ra4)*zqsat(:)*&
&zcor(:)/(zt(:)-ra4)**2)/(1.0+zlcpe(:)*ra2*(tmelt-ra4)*zqsat(:)*zcor(:)/(zt(:)-ra4)**2)/(1.0+zlcpe(:)*ra2*(tmelt-ra4)*zqsat(:&
&)*zcor(:)/(zt(:)-ra4)**2))
      zprsl_ad(:) = zprsl_ad(:)+zdqdt_ad(:)*(0.5-sign(0.5,zprsl(:)-gamma*(zqsat(:)-zq(:))*dsigma(jlev)/deltsec2/(1.0+zlcpe(:)*ra2*&
&(tmelt-ra4)*zqsat(:)*zcor(:)/(zt(:)-ra4)**2)))
      zq_ad(:) = zq_ad(:)-zdqdt_ad(:)*(0.5+sign(0.5,zprsl(:)-gamma*(zqsat(:)-zq(:))*dsigma(jlev)/deltsec2/(1.0+zlcpe(:)*ra2*(tmelt-&
&ra4)*zqsat(:)*zcor(:)/(zt(:)-ra4)**2)))*(gamma*dsigma(jlev)/deltsec2/(1.0+zlcpe(:)*ra2*(tmelt-ra4)*zqsat(:)*zcor(:)/(zt(:)-&
&ra4)**2))
      zqsat_ad(:) = zqsat_ad(:)+zdqdt_ad(:)*(0.5+sign(0.5,zprsl(:)-gamma*(zqsat(:)-zq(:))*dsigma(jlev)/deltsec2/(1.0+zlcpe(:)*ra2*&
&(tmelt-ra4)*zqsat(:)*zcor(:)/(zt(:)-ra4)**2)))*((gamma*dsigma(jlev)/deltsec2-gamma*(zqsat(:)-zq(:))*dsigma(jlev)/deltsec2*&
&(zlcpe(:)*ra2*(tmelt-ra4)*zcor(:)/(zt(:)-ra4)**2)/(1.0+zlcpe(:)*ra2*(tmelt-ra4)*zqsat(:)*zcor(:)/(zt(:)-ra4)**2))/(1.0+&
&zlcpe(:)*ra2*(tmelt-ra4)*zqsat(:)*zcor(:)/(zt(:)-ra4)**2))
      zt_ad(:) = zt_ad(:)+zdqdt_ad(:)*(0.5+sign(0.5,zprsl(:)-gamma*(zqsat(:)-zq(:))*dsigma(jlev)/deltsec2/(1.0+zlcpe(:)*ra2*(tmelt-&
&ra4)*zqsat(:)*zcor(:)/(zt(:)-ra4)**2)))*(gamma*(zqsat(:)-zq(:))*dsigma(jlev)/deltsec2*(2*(zlcpe(:)*ra2*(tmelt-ra4)*zqsat(:)*&
&zcor(:))*(zt(:)-ra4)/(zt(:)-ra4)**2/(zt(:)-ra4)**2)/(1.0+zlcpe(:)*ra2*(tmelt-ra4)*zqsat(:)*zcor(:)/(zt(:)-ra4)**2)/(1.0+&
&zlcpe(:)*ra2*(tmelt-ra4)*zqsat(:)*zcor(:)/(zt(:)-ra4)**2))
      zdqdt_ad(:) = 0.
      dq_ad(:,jlev) = dq_ad(:,jlev)-zlcpe_ad(:)*(als*acpd*adv/(acpd*(1.+adv*dq(:,jlev)))/(acpd*(1.+adv*dq(:,jlev))))
      zlcpe_ad(:) = 0.
    end where
    whcondq = zq(:) < zqsat(:) .and. zprc(:) > zeps
    where (whcondq)
      zlcpe(:) = alv/(acpd*(1.+adv*dq(:,jlev)))
      zdqdt(:) = amin1(gamma*(zqsat(:)-zq(:))*dsigma(jlev)/deltsec2/(1.0+zlcpe(:)*ra2*(tmelt-ra4)*zqsat(:)*zcor(:)/(zt(:)-ra4)**2),&
&zprc(:))
      zdqdt(:) = zdqdt(:)/dsigma(jlev)
      zdqdt_ad(:) = zdqdt_ad(:)+zdqdtl_ad(:,jlev)
      zdqdt_ad(:) = zdqdt_ad(:)-zdtdt_ad(:,jlev)*zlcpe(:)
      zlcpe_ad(:) = zlcpe_ad(:)-zdtdt_ad(:,jlev)*zdqdt(:)
      zdqdt_ad(:) = zdqdt_ad(:)/dsigma(jlev)
      zdqdt_ad(:) = zdqdt_ad(:)-zprc_ad(:)
      zcor_ad(:) = zcor_ad(:)-zdqdt_ad(:)*(0.5+sign(0.5,zprc(:)-gamma*(zqsat(:)-zq(:))*dsigma(jlev)/deltsec2/(1.0+zlcpe(:)*ra2*&
&(tmelt-ra4)*zqsat(:)*zcor(:)/(zt(:)-ra4)**2)))*(gamma*(zqsat(:)-zq(:))*dsigma(jlev)/deltsec2*(zlcpe(:)*ra2*(tmelt-ra4)*&
&zqsat(:)/(zt(:)-ra4)**2)/(1.0+zlcpe(:)*ra2*(tmelt-ra4)*zqsat(:)*zcor(:)/(zt(:)-ra4)**2)/(1.0+zlcpe(:)*ra2*(tmelt-ra4)*&
&zqsat(:)*zcor(:)/(zt(:)-ra4)**2))
      zlcpe_ad(:) = zlcpe_ad(:)-zdqdt_ad(:)*(0.5+sign(0.5,zprc(:)-gamma*(zqsat(:)-zq(:))*dsigma(jlev)/deltsec2/(1.0+zlcpe(:)*ra2*&
&(tmelt-ra4)*zqsat(:)*zcor(:)/(zt(:)-ra4)**2)))*(gamma*(zqsat(:)-zq(:))*dsigma(jlev)/deltsec2*(ra2*(tmelt-ra4)*zqsat(:)*&
&zcor(:)/(zt(:)-ra4)**2)/(1.0+zlcpe(:)*ra2*(tmelt-ra4)*zqsat(:)*zcor(:)/(zt(:)-ra4)**2)/(1.0+zlcpe(:)*ra2*(tmelt-ra4)*zqsat(:&
&)*zcor(:)/(zt(:)-ra4)**2))
      zprc_ad(:) = zprc_ad(:)+zdqdt_ad(:)*(0.5-sign(0.5,zprc(:)-gamma*(zqsat(:)-zq(:))*dsigma(jlev)/deltsec2/(1.0+zlcpe(:)*ra2*&
&(tmelt-ra4)*zqsat(:)*zcor(:)/(zt(:)-ra4)**2)))
      zq_ad(:) = zq_ad(:)-zdqdt_ad(:)*(0.5+sign(0.5,zprc(:)-gamma*(zqsat(:)-zq(:))*dsigma(jlev)/deltsec2/(1.0+zlcpe(:)*ra2*(tmelt-&
&ra4)*zqsat(:)*zcor(:)/(zt(:)-ra4)**2)))*(gamma*dsigma(jlev)/deltsec2/(1.0+zlcpe(:)*ra2*(tmelt-ra4)*zqsat(:)*zcor(:)/(zt(:)-&
&ra4)**2))
      zqsat_ad(:) = zqsat_ad(:)+zdqdt_ad(:)*(0.5+sign(0.5,zprc(:)-gamma*(zqsat(:)-zq(:))*dsigma(jlev)/deltsec2/(1.0+zlcpe(:)*ra2*&
&(tmelt-ra4)*zqsat(:)*zcor(:)/(zt(:)-ra4)**2)))*((gamma*dsigma(jlev)/deltsec2-gamma*(zqsat(:)-zq(:))*dsigma(jlev)/deltsec2*&
&(zlcpe(:)*ra2*(tmelt-ra4)*zcor(:)/(zt(:)-ra4)**2)/(1.0+zlcpe(:)*ra2*(tmelt-ra4)*zqsat(:)*zcor(:)/(zt(:)-ra4)**2))/(1.0+&
&zlcpe(:)*ra2*(tmelt-ra4)*zqsat(:)*zcor(:)/(zt(:)-ra4)**2))
      zt_ad(:) = zt_ad(:)+zdqdt_ad(:)*(0.5+sign(0.5,zprc(:)-gamma*(zqsat(:)-zq(:))*dsigma(jlev)/deltsec2/(1.0+zlcpe(:)*ra2*(tmelt-&
&ra4)*zqsat(:)*zcor(:)/(zt(:)-ra4)**2)))*(gamma*(zqsat(:)-zq(:))*dsigma(jlev)/deltsec2*(2*(zlcpe(:)*ra2*(tmelt-ra4)*zqsat(:)*&
&zcor(:))*(zt(:)-ra4)/(zt(:)-ra4)**2/(zt(:)-ra4)**2)/(1.0+zlcpe(:)*ra2*(tmelt-ra4)*zqsat(:)*zcor(:)/(zt(:)-ra4)**2)/(1.0+&
&zlcpe(:)*ra2*(tmelt-ra4)*zqsat(:)*zcor(:)/(zt(:)-ra4)**2))
      zdqdt_ad(:) = 0.
      dq_ad(:,jlev) = dq_ad(:,jlev)-zlcpe_ad(:)*(alv*acpd*adv/(acpd*(1.+adv*dq(:,jlev)))/(acpd*(1.+adv*dq(:,jlev))))
      zlcpe_ad(:) = 0.
    end where
    whcondr = zq(:) < zqsat(:) .and. zprl(:) > zeps
    where (whcondr)
      zlcpe(:) = alv/(acpd*(1.+adv*dq(:,jlev)))
      zdqdt(:) = amin1(gamma*(zqsat(:)-zq(:))*dsigma(jlev)/deltsec2/(1.0+zlcpe(:)*ra2*(tmelt-ra4)*zqsat(:)*zcor(:)/(zt(:)-ra4)**2),&
&zprl(:))
      zdqdt(:) = zdqdt(:)/dsigma(jlev)
      zdqdt_ad(:) = zdqdt_ad(:)+zdqdtl_ad(:,jlev)
      zdqdt_ad(:) = zdqdt_ad(:)-zdtdt_ad(:,jlev)*zlcpe(:)
      zlcpe_ad(:) = zlcpe_ad(:)-zdtdt_ad(:,jlev)*zdqdt(:)
      zdqdt_ad(:) = zdqdt_ad(:)/dsigma(jlev)
      zdqdt_ad(:) = zdqdt_ad(:)-zprl_ad(:)
      zcor_ad(:) = zcor_ad(:)-zdqdt_ad(:)*(0.5+sign(0.5,zprl(:)-gamma*(zqsat(:)-zq(:))*dsigma(jlev)/deltsec2/(1.0+zlcpe(:)*ra2*&
&(tmelt-ra4)*zqsat(:)*zcor(:)/(zt(:)-ra4)**2)))*(gamma*(zqsat(:)-zq(:))*dsigma(jlev)/deltsec2*(zlcpe(:)*ra2*(tmelt-ra4)*&
&zqsat(:)/(zt(:)-ra4)**2)/(1.0+zlcpe(:)*ra2*(tmelt-ra4)*zqsat(:)*zcor(:)/(zt(:)-ra4)**2)/(1.0+zlcpe(:)*ra2*(tmelt-ra4)*&
&zqsat(:)*zcor(:)/(zt(:)-ra4)**2))
      zlcpe_ad(:) = zlcpe_ad(:)-zdqdt_ad(:)*(0.5+sign(0.5,zprl(:)-gamma*(zqsat(:)-zq(:))*dsigma(jlev)/deltsec2/(1.0+zlcpe(:)*ra2*&
&(tmelt-ra4)*zqsat(:)*zcor(:)/(zt(:)-ra4)**2)))*(gamma*(zqsat(:)-zq(:))*dsigma(jlev)/deltsec2*(ra2*(tmelt-ra4)*zqsat(:)*&
&zcor(:)/(zt(:)-ra4)**2)/(1.0+zlcpe(:)*ra2*(tmelt-ra4)*zqsat(:)*zcor(:)/(zt(:)-ra4)**2)/(1.0+zlcpe(:)*ra2*(tmelt-ra4)*zqsat(:&
&)*zcor(:)/(zt(:)-ra4)**2))
      zprl_ad(:) = zprl_ad(:)+zdqdt_ad(:)*(0.5-sign(0.5,zprl(:)-gamma*(zqsat(:)-zq(:))*dsigma(jlev)/deltsec2/(1.0+zlcpe(:)*ra2*&
&(tmelt-ra4)*zqsat(:)*zcor(:)/(zt(:)-ra4)**2)))
      zq_ad(:) = zq_ad(:)-zdqdt_ad(:)*(0.5+sign(0.5,zprl(:)-gamma*(zqsat(:)-zq(:))*dsigma(jlev)/deltsec2/(1.0+zlcpe(:)*ra2*(tmelt-&
&ra4)*zqsat(:)*zcor(:)/(zt(:)-ra4)**2)))*(gamma*dsigma(jlev)/deltsec2/(1.0+zlcpe(:)*ra2*(tmelt-ra4)*zqsat(:)*zcor(:)/(zt(:)-&
&ra4)**2))
      zqsat_ad(:) = zqsat_ad(:)+zdqdt_ad(:)*(0.5+sign(0.5,zprl(:)-gamma*(zqsat(:)-zq(:))*dsigma(jlev)/deltsec2/(1.0+zlcpe(:)*ra2*&
&(tmelt-ra4)*zqsat(:)*zcor(:)/(zt(:)-ra4)**2)))*((gamma*dsigma(jlev)/deltsec2-gamma*(zqsat(:)-zq(:))*dsigma(jlev)/deltsec2*&
&(zlcpe(:)*ra2*(tmelt-ra4)*zcor(:)/(zt(:)-ra4)**2)/(1.0+zlcpe(:)*ra2*(tmelt-ra4)*zqsat(:)*zcor(:)/(zt(:)-ra4)**2))/(1.0+&
&zlcpe(:)*ra2*(tmelt-ra4)*zqsat(:)*zcor(:)/(zt(:)-ra4)**2))
      zt_ad(:) = zt_ad(:)+zdqdt_ad(:)*(0.5+sign(0.5,zprl(:)-gamma*(zqsat(:)-zq(:))*dsigma(jlev)/deltsec2/(1.0+zlcpe(:)*ra2*(tmelt-&
&ra4)*zqsat(:)*zcor(:)/(zt(:)-ra4)**2)))*(gamma*(zqsat(:)-zq(:))*dsigma(jlev)/deltsec2*(2*(zlcpe(:)*ra2*(tmelt-ra4)*zqsat(:)*&
&zcor(:))*(zt(:)-ra4)/(zt(:)-ra4)**2/(zt(:)-ra4)**2)/(1.0+zlcpe(:)*ra2*(tmelt-ra4)*zqsat(:)*zcor(:)/(zt(:)-ra4)**2)/(1.0+&
&zlcpe(:)*ra2*(tmelt-ra4)*zqsat(:)*zcor(:)/(zt(:)-ra4)**2))
      zdqdt_ad(:) = 0.
      dq_ad(:,jlev) = dq_ad(:,jlev)-zlcpe_ad(:)*(alv*acpd*adv/(acpd*(1.+adv*dq(:,jlev)))/(acpd*(1.+adv*dq(:,jlev))))
      zlcpe_ad(:) = 0.
    end where
    zqsat = mkrain_zqsat_5h(:,jlev)
    zqsat(:) = amin1(zqsat(:),rdbrv)
    zqsat(:) = zqsat(:)*zcor(:)
    whconds = zqsat(:) < 0.0
    where (whconds)
      zqsat_ad(:) = 0.
