    zebs(:,jlev) = zkdiff(:,jlev)/(dsigma(jlev)+zkdiff(:,jlev)+zkdiff(:,jlem)*(1.-zebs(:,jlem)))
    zqn(:,jlev) = (zq(:,jlev)*dsigma(jlev)+zkdiff(:,jlem)*zqn(:,jlem))/(dsigma(jlev)+zkdiff(:,jlev)+zkdiff(:,jlem)*(1.-zebs(:,jlem)&
&))
  end where
end do
where (kshallow(:) > 0)
  zqn(:,nlev) = (zq(:,nlev)*dsigma(nlev)+zkdiff(:,nlem)*zqn(:,nlem))/(dsigma(nlev)+zkdiff(:,nlem)*(1.-zebs(:,nlem)))
end where
!$taf INCOMPLETE mkshallow_zqn_3h
mkshallow_zqn_3h(:,:,1) = zqn
do jlev = 1, nlem
  where (kshallow(:) > 0)
    zkdiff(:,jlev) = zkdiff(:,jlev)*zskaph(jlev)
  end where
end do
zebs = 0.
ztn = 0.
where (kshallow(:) > 0)
  zebs(:,1) = zkdiff(:,1)/(dsigma(1)+zkdiff(:,1)/zskap(1))
  ztn(:,1) = dsigma(1)*zt(:,1)/(dsigma(1)+zkdiff(:,1)/zskap(1))
end where
do jlev = 2, nlem
  jlem = jlev-1
  where (kshallow(:) > 0)
    zebs(:,jlev) = zkdiff(:,jlev)/(dsigma(jlev)+(zkdiff(:,jlev)+zkdiff(:,jlem)*(1.-zebs(:,jlem)/zskap(jlem)))/zskap(jlev))
    ztn(:,jlev) = (zt(:,jlev)*dsigma(jlev)+zkdiff(:,jlem)/zskap(jlem)*ztn(:,jlem))/(dsigma(jlev)+(zkdiff(:,jlev)+zkdiff(:,jlem)*&
&(1.-zebs(:,jlem)/zskap(jlem)))/zskap(jlev))
  end where
end do
!$taf INCOMPLETE mkshallow_ztn_5h
mkshallow_ztn_5h(:,:,1) = ztn
!$taf INCOMPLETE mkshallow_zebs_4h
mkshallow_zebs_4h(:,:,1) = zebs
where (kshallow(:) > 0)
  ztn(:,nlev) = (zt(:,nlev)*dsigma(nlev)+zkdiff(:,nlem)*ztn(:,nlem)/zskap(nlem))/(dsigma(nlev)+zkdiff(:,nlem)/zskap(nlev)*(1.-&
&zebs(:,nlem)/zskap(nlem)))
end where
!$taf INCOMPLETE mkshallow_ztn_6h
mkshallow_ztn_6h(:,:,1) = ztn
if (nmoment == 1) then
  zu(:,:) = du(:,1:nlev)
  zv(:,:) = dv(:,1:nlev)
  where (kshallow(:) > 0)
    zebs(:,1) = zkdiff(:,1)/(dsigma(1)+zkdiff(:,1))
    zun(:,1) = dsigma(1)*zu(:,1)/(dsigma(1)+zkdiff(:,1))
    zvn(:,1) = dsigma(1)*zv(:,1)/(dsigma(1)+zkdiff(:,1))
  end where
  do jlev = 2, nlem
    jlem = jlev-1
    where (kshallow > 0)
      zebs(:,jlev) = zkdiff(:,jlev)/(dsigma(jlev)+zkdiff(:,jlev)+zkdiff(:,jlem)*(1.-zebs(:,jlem)))
      zun(:,jlev) = (zu(:,jlev)*dsigma(jlev)+zkdiff(:,jlem)*zun(:,jlem))/(dsigma(jlev)+zkdiff(:,jlev)+zkdiff(:,jlem)*(1.-zebs(:,&
&jlem)))
      zvn(:,jlev) = (zv(:,jlev)*dsigma(jlev)+zkdiff(:,jlem)*zvn(:,jlem))/(dsigma(jlev)+zkdiff(:,jlev)+zkdiff(:,jlem)*(1.-zebs(:,&
&jlem)))
    end where
  end do
  where (kshallow(:) > 0)
    zun(:,nlev) = (zu(:,nlev)*dsigma(nlev)+zkdiff(:,nlem)*zun(:,nlem))/(dsigma(nlev)+zkdiff(:,nlem)*(1.-zebs(:,nlem)))
    zvn(:,nlev) = (zv(:,nlev)*dsigma(nlev)+zkdiff(:,nlem)*zvn(:,nlem))/(dsigma(nlev)+zkdiff(:,nlem)*(1.-zebs(:,nlem)))
  end where
  do jlev = nlem, 1, -1
    jlep = jlev+1
    where (kshallow(:) > 0)
      zun(:,jlev) = zun(:,jlev)+zebs(:,jlev)*zun(:,jlep)
      zvn(:,jlev) = zvn(:,jlev)+zebs(:,jlev)*zvn(:,jlep)
    end where
  end do
!$taf INCOMPLETE mkshallow_zvn_8h
  mkshallow_zvn_8h(:,:,1) = zvn
!$taf INCOMPLETE mkshallow_zun_7h
  mkshallow_zun_7h(:,:,1) = zun
  if (ndheat > 0) then
    do jlev = 1, nlev
      where (kshallow(:) > 0)
        zke(:,jlev) = 0.5*(zu(:,jlev)*zu(:,jlev)+zv(:,jlev)*zv(:,jlev))
      end where
    end do
    where (kshallow(:) > 0)
      zebs(:,1) = zkdiff(:,1)/(dsigma(1)+zkdiff(:,1))
      zken(:,1) = dsigma(1)*zke(:,1)/(dsigma(1)+zkdiff(:,1))
    end where
    do jlev = 2, nlem
      jlem = jlev-1
      where (kshallow(:) > 0)
        zebs(:,jlev) = zkdiff(:,jlev)/(dsigma(jlev)+zkdiff(:,jlev)+zkdiff(:,jlem)*(1.-zebs(:,jlem)))
        zken(:,jlev) = (zke(:,jlev)*dsigma(jlev)+zkdiff(:,jlem)*zken(:,jlem))/(dsigma(jlev)+zkdiff(:,jlev)+zkdiff(:,jlem)*(1.-&
&zebs(:,jlem)))
      end where
    end do
    where (kshallow(:) > 0)
      zken(:,nlev) = (zke(:,nlev)*dsigma(nlev)+zkdiff(:,nlem)*zken(:,nlem))/(dsigma(nlev)+zkdiff(:,nlem)*(1.-zebs(:,nlem)))
    end where
!$taf INCOMPLETE mkshallow_zken_10h
    mkshallow_zken_10h(:,:,1) = zken(:,2:nlev)
!$taf INCOMPLETE mkshallow_zebs_9h
    mkshallow_zebs_9h(:,:,1) = zebs(:,1:nlem)
    do jlev = nlem, 1, -1
      jlep = jlev+1
      where (kshallow(:) > 0)
        zken(:,jlev) = zken(:,jlev)+zebs(:,jlev)*zken(:,jlep)
      end where
    end do
!$taf INCOMPLETE mkshallow_zken_11h
    mkshallow_zken_11h(:,:,1) = zken(:,:)
  endif
endif

!----------------------------------------------
! ADJOINT COMPUTATIONS
!----------------------------------------------
!$taf INCOMPLETE zebs_ad,zkdiff_ad,zken_ad,zqn_ad,ztn_ad,zun_ad,zvn_ad
ztn = mkshallow_ztn_6h(:,:,1)
!$taf INCOMPLETE zebs_ad,zken_ad,zun_ad,zvn_ad
if (nmoment == 1) then
!$taf INCOMPLETE zebs_ad,zken_ad,zun_ad,zvn_ad
  zvn = mkshallow_zvn_8h(:,:,1)
  zun = mkshallow_zun_7h(:,:,1)
!$taf INCOMPLETE zebs_ad,zken_ad
  if (ndheat > 0) then
!$taf INCOMPLETE zebs_ad,zken_ad
    zebs(:,1:nlem) = mkshallow_zebs_9h(:,:,1)
    zken(:,:) = mkshallow_zken_11h(:,:,1)
    do jlev = nlev, 1, -1
      where (kshallow(:) > 0)
        zdtdt_ad(:,jlev) = 0.
        zdtdt_ad(:,jlev) = zdtdt_ad(:,jlev)+pdtdt_ad(:,jlev)
        dq_ad(:,jlev) = dq_ad(:,jlev)+zdtdt_ad(:,jlev)*(0.5*((zun(:,jlev)*zun(:,jlev)-zu(:,jlev)*zu(:,jlev)+zvn(:,jlev)*zvn(:,jlev)&
&-zv(:,jlev)*zv(:,jlev))/deltsec2-(zken(:,jlev)-zke(:,jlev))/deltsec2)/acpd*adv/(1.+adv*dq(:,jlev))/(1.+adv*dq(:,jlev)))
        zke_ad(:,jlev) = zke_ad(:,jlev)+zdtdt_ad(:,jlev)*(0.5*((-1)/deltsec2)/acpd/(1.+adv*dq(:,jlev)))
        zken_ad(:,jlev) = zken_ad(:,jlev)+zdtdt_ad(:,jlev)*(0.5*(1/deltsec2)/acpd/(1.+adv*dq(:,jlev)))
        zu_ad(:,jlev) = zu_ad(:,jlev)+zdtdt_ad(:,jlev)*(0.5*(2*zu(:,jlev)/deltsec2)/acpd/(1.+adv*dq(:,jlev)))
        zun_ad(:,jlev) = zun_ad(:,jlev)-zdtdt_ad(:,jlev)*(0.5*(2*zun(:,jlev)/deltsec2)/acpd/(1.+adv*dq(:,jlev)))
        zv_ad(:,jlev) = zv_ad(:,jlev)+zdtdt_ad(:,jlev)*(0.5*(2*zv(:,jlev)/deltsec2)/acpd/(1.+adv*dq(:,jlev)))
        zvn_ad(:,jlev) = zvn_ad(:,jlev)-zdtdt_ad(:,jlev)*(0.5*(2*zvn(:,jlev)/deltsec2)/acpd/(1.+adv*dq(:,jlev)))
        zdtdt_ad(:,jlev) = 0.
      end where
    end do
    zken(:,2:nlev) = mkshallow_zken_10h(:,:,1)
    do jlev = nlem, 2, -1
      jlep = jlev+1
      where (kshallow(:) > 0)
        zken(:,jlev) = zken(:,jlev)+zebs(:,jlev)*zken(:,jlep)
      end where
    end do
    do jlev = 1, nlem
      jlep = jlev+1
      where (kshallow(:) > 0)
        zkenj_ad = zken_ad(:,jlev)
        zebs_ad(:,jlev) = zebs_ad(:,jlev)+zkenj_ad*zken(:,jlep)
        zken_ad(:,jlep) = zken_ad(:,jlep)+zkenj_ad*zebs(:,jlev)
        zken_ad(:,jlev) = zkenj_ad
      end where
    end do
    zebs = mkshallow_zebs_4h(:,:,1)
    where (kshallow(:) > 0)
      zebs(:,1) = zkdiff(:,1)/(dsigma(1)+zkdiff(:,1))
    end where
    do jlev = 2, nlem
      jlem = jlev-1
      where (kshallow > 0)
        zebs(:,jlev) = zkdiff(:,jlev)/(dsigma(jlev)+zkdiff(:,jlev)+zkdiff(:,jlem)*(1.-zebs(:,jlem)))
      end where
    end do
    where (kshallow(:) > 0)
      zebs(:,1) = zkdiff(:,1)/(dsigma(1)+zkdiff(:,1))
      zken(:,1) = dsigma(1)*zke(:,1)/(dsigma(1)+zkdiff(:,1))
    end where
    do jlev = 2, nlem
      jlem = jlev-1
      where (kshallow(:) > 0)
        zebs(:,jlev) = zkdiff(:,jlev)/(dsigma(jlev)+zkdiff(:,jlev)+zkdiff(:,jlem)*(1.-zebs(:,jlem)))
        zken(:,jlev) = (zke(:,jlev)*dsigma(jlev)+zkdiff(:,jlem)*zken(:,jlem))/(dsigma(jlev)+zkdiff(:,jlev)+zkdiff(:,jlem)*(1.-&
&zebs(:,jlem)))
      end where
    end do
    where (kshallow(:) > 0)
      zebs_ad(:,nlem) = zebs_ad(:,nlem)+zken_ad(:,nlev)*((zke(:,nlev)*dsigma(nlev)+zkdiff(:,nlem)*zken(:,nlem))*zkdiff(:,nlem)/&
&(dsigma(nlev)+zkdiff(:,nlem)*(1.-zebs(:,nlem)))/(dsigma(nlev)+zkdiff(:,nlem)*(1.-zebs(:,nlem))))
      zkdiff_ad(:,nlem) = zkdiff_ad(:,nlem)+zken_ad(:,nlev)*((zken(:,nlem)-(zke(:,nlev)*dsigma(nlev)+zkdiff(:,nlem)*zken(:,nlem))*&
&(1.-zebs(:,nlem))/(dsigma(nlev)+zkdiff(:,nlem)*(1.-zebs(:,nlem))))/(dsigma(nlev)+zkdiff(:,nlem)*(1.-zebs(:,nlem))))
      zke_ad(:,nlev) = zke_ad(:,nlev)+zken_ad(:,nlev)*(dsigma(nlev)/(dsigma(nlev)+zkdiff(:,nlem)*(1.-zebs(:,nlem))))
      zken_ad(:,nlem) = zken_ad(:,nlem)+zken_ad(:,nlev)*(zkdiff(:,nlem)/(dsigma(nlev)+zkdiff(:,nlem)*(1.-zebs(:,nlem))))
      zken_ad(:,nlev) = 0.
    end where
    zebs = mkshallow_zebs_4h(:,:,1)
    where (kshallow(:) > 0)
      zebs(:,1) = zkdiff(:,1)/(dsigma(1)+zkdiff(:,1))
    end where
    do jlev = 2, nlem
      jlem = jlev-1
      where (kshallow > 0)
        zebs(:,jlev) = zkdiff(:,jlev)/(dsigma(jlev)+zkdiff(:,jlev)+zkdiff(:,jlem)*(1.-zebs(:,jlem)))
      end where
    end do
    where (kshallow(:) > 0)
      zebs(:,1) = zkdiff(:,1)/(dsigma(1)+zkdiff(:,1))
      zken(:,1) = dsigma(1)*zke(:,1)/(dsigma(1)+zkdiff(:,1))
    end where
!$taf INCOMPLETE zebs_ad,zken_ad
    do jlev = 2, nlem-1
      jlem = jlev-1
      where (kshallow(:) > 0)
        zebs(:,jlev) = zkdiff(:,jlev)/(dsigma(jlev)+zkdiff(:,jlev)+zkdiff(:,jlem)*(1.-zebs(:,jlem)))
        zken(:,jlev) = (zke(:,jlev)*dsigma(jlev)+zkdiff(:,jlem)*zken(:,jlem))/(dsigma(jlev)+zkdiff(:,jlev)+zkdiff(:,jlem)*(1.-&
&zebs(:,jlem)))
      end where
    end do
    do jlev = nlem, 2, -1
!$taf INCOMPLETE zebs
      jlem = jlev-1
!$taf INCOMPLETE zebs
      where (kshallow(:) > 0)
        zebs(:,jlev) = zkdiff(:,jlev)/(dsigma(jlev)+zkdiff(:,jlev)+zkdiff(:,jlem)*(1.-zebs(:,jlem)))
        zkenk_ad = zken_ad(:,jlev)
        zken_ad(:,jlev) = 0.
        zebs_ad(:,jlem) = zebs_ad(:,jlem)+zkenk_ad*((zke(:,jlev)*dsigma(jlev)+zkdiff(:,jlem)*zken(:,jlem))*zkdiff(:,jlem)/&
&(dsigma(jlev)+zkdiff(:,jlev)+zkdiff(:,jlem)*(1.-zebs(:,jlem)))/(dsigma(jlev)+zkdiff(:,jlev)+zkdiff(:,jlem)*(1.-zebs(:,jlem))))
        zkdiff_ad(:,jlem) = zkdiff_ad(:,jlem)+zkenk_ad*((zken(:,jlem)-(zke(:,jlev)*dsigma(jlev)+zkdiff(:,jlem)*zken(:,jlem))*(1.-&
&zebs(:,jlem))/(dsigma(jlev)+zkdiff(:,jlev)+zkdiff(:,jlem)*(1.-zebs(:,jlem))))/(dsigma(jlev)+zkdiff(:,jlev)+zkdiff(:,jlem)*&
&(1.-zebs(:,jlem))))
        zkdiff_ad(:,jlev) = zkdiff_ad(:,jlev)-zkenk_ad*((zke(:,jlev)*dsigma(jlev)+zkdiff(:,jlem)*zken(:,jlem))/(dsigma(jlev)+&
&zkdiff(:,jlev)+zkdiff(:,jlem)*(1.-zebs(:,jlem)))/(dsigma(jlev)+zkdiff(:,jlev)+zkdiff(:,jlem)*(1.-zebs(:,jlem))))
        zke_ad(:,jlev) = zke_ad(:,jlev)+zkenk_ad*(dsigma(jlev)/(dsigma(jlev)+zkdiff(:,jlev)+zkdiff(:,jlem)*(1.-zebs(:,jlem))))
        zken_ad(:,jlem) = zken_ad(:,jlem)+zkenk_ad*(zkdiff(:,jlem)/(dsigma(jlev)+zkdiff(:,jlev)+zkdiff(:,jlem)*(1.-zebs(:,jlem))))
        zebsl_ad = zebs_ad(:,jlev)
        zebs_ad(:,jlev) = 0.
        zebs_ad(:,jlem) = zebs_ad(:,jlem)+zebsl_ad*(zkdiff(:,jlev)*zkdiff(:,jlem)/(dsigma(jlev)+zkdiff(:,jlev)+zkdiff(:,jlem)*(1.-&
&zebs(:,jlem)))/(dsigma(jlev)+zkdiff(:,jlev)+zkdiff(:,jlem)*(1.-zebs(:,jlem))))
        zkdiff_ad(:,jlem) = zkdiff_ad(:,jlem)-zebsl_ad*(zkdiff(:,jlev)*(1.-zebs(:,jlem))/(dsigma(jlev)+zkdiff(:,jlev)+zkdiff(:,&
&jlem)*(1.-zebs(:,jlem)))/(dsigma(jlev)+zkdiff(:,jlev)+zkdiff(:,jlem)*(1.-zebs(:,jlem))))
        zkdiff_ad(:,jlev) = zkdiff_ad(:,jlev)+zebsl_ad*((1-zkdiff(:,jlev)/(dsigma(jlev)+zkdiff(:,jlev)+zkdiff(:,jlem)*(1.-zebs(:,&
&jlem))))/(dsigma(jlev)+zkdiff(:,jlev)+zkdiff(:,jlem)*(1.-zebs(:,jlem))))
      end where
    end do
    where (kshallow(:) > 0)
      zkdiff_ad(:,1) = zkdiff_ad(:,1)-zken_ad(:,1)*(dsigma(1)*zke(:,1)/(dsigma(1)+zkdiff(:,1))/(dsigma(1)+zkdiff(:,1)))
      zke_ad(:,1) = zke_ad(:,1)+zken_ad(:,1)*(dsigma(1)/(dsigma(1)+zkdiff(:,1)))
      zken_ad(:,1) = 0.
      zkdiff_ad(:,1) = zkdiff_ad(:,1)+zebs_ad(:,1)*((1-zkdiff(:,1)/(dsigma(1)+zkdiff(:,1)))/(dsigma(1)+zkdiff(:,1)))
      zebs_ad(:,1) = 0.
    end where
    do jlev = nlev, 1, -1
      where (kshallow(:) > 0)
        zu_ad(:,jlev) = zu_ad(:,jlev)+zke_ad(:,jlev)*zu(:,jlev)
        zv_ad(:,jlev) = zv_ad(:,jlev)+zke_ad(:,jlev)*zv(:,jlev)
        zke_ad(:,jlev) = 0.
      end where
    end do
  endif
  do jlev = nlev, 1, -1
    where (kshallow(:) > 0)
      zdvdt_ad(:,jlev) = zdvdt_ad(:,jlev)+dvdt_ad(:,jlev)
      zdudt_ad(:,jlev) = zdudt_ad(:,jlev)+dudt_ad(:,jlev)
      zv_ad(:,jlev) = zv_ad(:,jlev)-zdvdt_ad(:,jlev)/deltsec2
      zvn_ad(:,jlev) = zvn_ad(:,jlev)+zdvdt_ad(:,jlev)/deltsec2
      zdvdt_ad(:,jlev) = 0.
      zu_ad(:,jlev) = zu_ad(:,jlev)-zdudt_ad(:,jlev)/deltsec2
      zun_ad(:,jlev) = zun_ad(:,jlev)+zdudt_ad(:,jlev)/deltsec2
      zdudt_ad(:,jlev) = 0.
    end where
  end do
  zebs = mkshallow_zebs_4h(:,:,1)
  where (kshallow(:) > 0)
    zebs(:,1) = zkdiff(:,1)/(dsigma(1)+zkdiff(:,1))
    zun(:,1) = dsigma(1)*zu(:,1)/(dsigma(1)+zkdiff(:,1))
    zvn(:,1) = dsigma(1)*zv(:,1)/(dsigma(1)+zkdiff(:,1))
  end where
  do jlev = 2, nlem
    jlem = jlev-1
    where (kshallow > 0)
      zebs(:,jlev) = zkdiff(:,jlev)/(dsigma(jlev)+zkdiff(:,jlev)+zkdiff(:,jlem)*(1.-zebs(:,jlem)))
      zun(:,jlev) = (zu(:,jlev)*dsigma(jlev)+zkdiff(:,jlem)*zun(:,jlem))/(dsigma(jlev)+zkdiff(:,jlev)+zkdiff(:,jlem)*(1.-zebs(:,&
&jlem)))
      zvn(:,jlev) = (zv(:,jlev)*dsigma(jlev)+zkdiff(:,jlem)*zvn(:,jlem))/(dsigma(jlev)+zkdiff(:,jlev)+zkdiff(:,jlem)*(1.-zebs(:,&
&jlem)))
    end where
  end do
  where (kshallow(:) > 0)
    zun(:,nlev) = (zu(:,nlev)*dsigma(nlev)+zkdiff(:,nlem)*zun(:,nlem))/(dsigma(nlev)+zkdiff(:,nlem)*(1.-zebs(:,nlem)))
    zvn(:,nlev) = (zv(:,nlev)*dsigma(nlev)+zkdiff(:,nlem)*zvn(:,nlem))/(dsigma(nlev)+zkdiff(:,nlem)*(1.-zebs(:,nlem)))
  end where
!$taf INCOMPLETE zun_ad,zvn_ad
  do jlev = nlem, 2, -1
    jlep = jlev+1
    where (kshallow(:) > 0)
      zun(:,jlev) = zun(:,jlev)+zebs(:,jlev)*zun(:,jlep)
      zvn(:,jlev) = zvn(:,jlev)+zebs(:,jlev)*zvn(:,jlep)
    end where
  end do
  do jlev = 1, nlem
    jlep = jlev+1
    where (kshallow(:) > 0)
      zvnj_ad = zvn_ad(:,jlev)
      zebs_ad(:,jlev) = zebs_ad(:,jlev)+zvnj_ad*zvn(:,jlep)
      zvn_ad(:,jlep) = zvn_ad(:,jlep)+zvnj_ad*zebs(:,jlev)
      zvn_ad(:,jlev) = zvnj_ad
      zunj_ad = zun_ad(:,jlev)
      zebs_ad(:,jlev) = zebs_ad(:,jlev)+zunj_ad*zun(:,jlep)
      zun_ad(:,jlep) = zun_ad(:,jlep)+zunj_ad*zebs(:,jlev)
      zun_ad(:,jlev) = zunj_ad
    end where
  end do
  zebs = mkshallow_zebs_4h(:,:,1)
  where (kshallow(:) > 0)
    zebs(:,1) = zkdiff(:,1)/(dsigma(1)+zkdiff(:,1))
    zun(:,1) = dsigma(1)*zu(:,1)/(dsigma(1)+zkdiff(:,1))
    zvn(:,1) = dsigma(1)*zv(:,1)/(dsigma(1)+zkdiff(:,1))
  end where
  do jlev = 2, nlem
    jlem = jlev-1
    where (kshallow > 0)
      zebs(:,jlev) = zkdiff(:,jlev)/(dsigma(jlev)+zkdiff(:,jlev)+zkdiff(:,jlem)*(1.-zebs(:,jlem)))
      zun(:,jlev) = (zu(:,jlev)*dsigma(jlev)+zkdiff(:,jlem)*zun(:,jlem))/(dsigma(jlev)+zkdiff(:,jlev)+zkdiff(:,jlem)*(1.-zebs(:,&
&jlem)))
      zvn(:,jlev) = (zv(:,jlev)*dsigma(jlev)+zkdiff(:,jlem)*zvn(:,jlem))/(dsigma(jlev)+zkdiff(:,jlev)+zkdiff(:,jlem)*(1.-zebs(:,&
&jlem)))
    end where
  end do
  where (kshallow(:) > 0)
    zebs_ad(:,nlem) = zebs_ad(:,nlem)+zvn_ad(:,nlev)*((zv(:,nlev)*dsigma(nlev)+zkdiff(:,nlem)*zvn(:,nlem))*zkdiff(:,nlem)/&
&(dsigma(nlev)+zkdiff(:,nlem)*(1.-zebs(:,nlem)))/(dsigma(nlev)+zkdiff(:,nlem)*(1.-zebs(:,nlem))))
    zkdiff_ad(:,nlem) = zkdiff_ad(:,nlem)+zvn_ad(:,nlev)*((zvn(:,nlem)-(zv(:,nlev)*dsigma(nlev)+zkdiff(:,nlem)*zvn(:,nlem))*(1.-&
&zebs(:,nlem))/(dsigma(nlev)+zkdiff(:,nlem)*(1.-zebs(:,nlem))))/(dsigma(nlev)+zkdiff(:,nlem)*(1.-zebs(:,nlem))))
    zv_ad(:,nlev) = zv_ad(:,nlev)+zvn_ad(:,nlev)*(dsigma(nlev)/(dsigma(nlev)+zkdiff(:,nlem)*(1.-zebs(:,nlem))))
    zvn_ad(:,nlem) = zvn_ad(:,nlem)+zvn_ad(:,nlev)*(zkdiff(:,nlem)/(dsigma(nlev)+zkdiff(:,nlem)*(1.-zebs(:,nlem))))
    zvn_ad(:,nlev) = 0.
    zebs_ad(:,nlem) = zebs_ad(:,nlem)+zun_ad(:,nlev)*((zu(:,nlev)*dsigma(nlev)+zkdiff(:,nlem)*zun(:,nlem))*zkdiff(:,nlem)/&
&(dsigma(nlev)+zkdiff(:,nlem)*(1.-zebs(:,nlem)))/(dsigma(nlev)+zkdiff(:,nlem)*(1.-zebs(:,nlem))))
    zkdiff_ad(:,nlem) = zkdiff_ad(:,nlem)+zun_ad(:,nlev)*((zun(:,nlem)-(zu(:,nlev)*dsigma(nlev)+zkdiff(:,nlem)*zun(:,nlem))*(1.-&
&zebs(:,nlem))/(dsigma(nlev)+zkdiff(:,nlem)*(1.-zebs(:,nlem))))/(dsigma(nlev)+zkdiff(:,nlem)*(1.-zebs(:,nlem))))
    zu_ad(:,nlev) = zu_ad(:,nlev)+zun_ad(:,nlev)*(dsigma(nlev)/(dsigma(nlev)+zkdiff(:,nlem)*(1.-zebs(:,nlem))))
