      zebs(:,jlev) = zkdiff(:,jlev)/(dsigma(jlev)+zkdiff(:,jlev)+zkdiff(:,jlem)*(1.-zebs(:,jlem)))
      zun(:,jlev) = (zu(:,jlev)*dsigma(jlev)+zkdiff(:,jlem)*zun(:,jlem))/(dsigma(jlev)+zkdiff(:,jlev)+zkdiff(:,jlem)*(1.-zebs(:,&
&jlem)))
      zvn(:,jlev) = (zv(:,jlev)*dsigma(jlev)+zkdiff(:,jlem)*zvn(:,jlem))/(dsigma(jlev)+zkdiff(:,jlev)+zkdiff(:,jlem)*(1.-zebs(:,&
&jlem)))
    end where
  end do
  where (kshallow(:) > 0)
    zun(:,nlev) = (zu(:,nlev)*dsigma(nlev)+zkdiff(:,nlem)*zun(:,nlem))/(dsigma(nlev)+zkdiff(:,nlem)*(1.-zebs(:,nlem)))
    zvn(:,nlev) = (zv(:,nlev)*dsigma(nlev)+zkdiff(:,nlem)*zvn(:,nlem))/(dsigma(nlev)+zkdiff(:,nlem)*(1.-zebs(:,nlem)))
  end where
!$taf INCOMPLETE zun,zvn
  do jlev = nlem, 1, -1
    jlep = jlev+1
    where (kshallow(:) > 0)
      zun(:,jlev) = zun(:,jlev)+zebs(:,jlev)*zun(:,jlep)
      zvn(:,jlev) = zvn(:,jlev)+zebs(:,jlev)*zvn(:,jlep)
    end where
  end do
  do jlev = 1, nlev
    where (kshallow(:) > 0)
      zdudt(:,jlev) = (zun(:,jlev)-zu(:,jlev))/deltsec2
      zdvdt(:,jlev) = (zvn(:,jlev)-zv(:,jlev))/deltsec2
      dudt(:,jlev) = dudt(:,jlev)+zdudt(:,jlev)
      dvdt(:,jlev) = dvdt(:,jlev)+zdvdt(:,jlev)
    end where
  end do
  if (ndheat > 0) then
    do jlev = 1, nlev
      where (kshallow(:) > 0)
        zke(:,jlev) = 0.5*(zu(:,jlev)*zu(:,jlev)+zv(:,jlev)*zv(:,jlev))
      end where
    end do
    where (kshallow(:) > 0)
      zebs(:,1) = zkdiff(:,1)/(dsigma(1)+zkdiff(:,1))
      zken(:,1) = dsigma(1)*zke(:,1)/(dsigma(1)+zkdiff(:,1))
    end where
!$taf INCOMPLETE zebs,zken
    do jlev = 2, nlem
      jlem = jlev-1
      where (kshallow(:) > 0)
        zebs(:,jlev) = zkdiff(:,jlev)/(dsigma(jlev)+zkdiff(:,jlev)+zkdiff(:,jlem)*(1.-zebs(:,jlem)))
        zken(:,jlev) = (zke(:,jlev)*dsigma(jlev)+zkdiff(:,jlem)*zken(:,jlem))/(dsigma(jlev)+zkdiff(:,jlev)+zkdiff(:,jlem)*(1.-&
&zebs(:,jlem)))
      end where
    end do
    where (kshallow(:) > 0)
      zken(:,nlev) = (zke(:,nlev)*dsigma(nlev)+zkdiff(:,nlem)*zken(:,nlem))/(dsigma(nlev)+zkdiff(:,nlem)*(1.-zebs(:,nlem)))
    end where
    do jlev = nlem, 1, -1
      jlep = jlev+1
      where (kshallow(:) > 0)
        zken(:,jlev) = zken(:,jlev)+zebs(:,jlev)*zken(:,jlep)
      end where
    end do
    do jlev = 1, nlev
      where (kshallow(:) > 0)
        zdtdt(:,jlev) = -(((zun(:,jlev)*zun(:,jlev)-zu(:,jlev)*zu(:,jlev)+zvn(:,jlev)*zvn(:,jlev)-zv(:,jlev)*zv(:,jlev))/deltsec2-&
&(zken(:,jlev)-zke(:,jlev))/deltsec2)*0.5/acpd/(1.+adv*dq(:,jlev)))
        pdtdt(:,jlev) = pdtdt(:,jlev)+zdtdt(:,jlev)
        zdtdt(:,jlev) = 0.
      end where
    end do
  endif
endif
if (nprint == 2) then
  allocate( zprf1(nlon*nlat,nlev) )
  allocate( zprf2(nlon*nlat,nlev) )
  allocate( zprf3(nlon*nlat,nlev) )
  allocate( zprf4(nlon*nlat,nlev) )
  allocate( zprf5(nlon*nlat) )
  allocate( zprf6(nlon*nlat) )
  allocate( zprf7(nlon*nlat) )
  allocate( zprf8(nhor) )
  allocate( zprf9(nhor) )
  allocate( zprf10(nhor) )
  zprf8(:) = real(klift(:))
  zprf9(:) = real(ktop(:))
  zprf10(:) = real(kshallow(:))
  call mpgagp( zprf1,pt,nlev )
  call mpgagp( zprf2,pq,nlev )
  call mpgagp( zprf3,pdtdt,nlev )
  call mpgagp( zprf4,pdqdt,nlev )
  call mpgagp( zprf5,zprf8,1 )
  call mpgagp( zprf6,zprf9,1 )
  call mpgagp( zprf7,zprf10,1 )
  deallocate( zprf8 )
  deallocate( zprf9 )
  deallocate( zprf10 )
  if (mypid == nroot) then
    write(unit=nud,fmt=*) 'In mkshallow:'
    write(unit=nud,fmt=*) 'kshallow= ',zprf7(nprhor),' total= ',sum(nint(zprf7))
    write(unit=nud,fmt=*) 'ilift= ',zprf5(nprhor),' itop= ',zprf6(nprhor)
    do jlev = 1, nlev
      zztn = zprf1(nprhor,jlev)+zprf3(nprhor,jlev)*deltsec2
      zzqn = zprf2(nprhor,jlev)+zprf4(nprhor,jlev)*deltsec2
      write(unit=nud,fmt=*) 'L= ',jlev,' t= ',zprf1(nprhor,jlev),' q= ',zprf2(nprhor,jlev)
      write(unit=nud,fmt=*) 'L= ',jlev,' tnew= ',zztn,' dtdt= ',zprf3(nprhor,jlev),' qnew= ',zzqn,' dqdt= ',zprf4(nprhor,jlev)
    end do
  endif
  deallocate( zprf1 )
  deallocate( zprf2 )
  deallocate( zprf3 )
  deallocate( zprf4 )
  deallocate( zprf5 )
  deallocate( zprf6 )
  deallocate( zprf7 )
endif
end subroutine mkshallow

subroutine rainini()
