namelist /rainmod_nl/ kbeta,nprl,nprc,ndca,ncsurf,nmoment,nshallow,nstorain,rcrit,clwcrit1,clwcrit2,pdeep,rkshallow,gamma,nclouds,&
&pdeepth,nevapprec,nbeta,rhbeta,rbeta

if (ntru == 21 .and. nlev == 5) then
  nshallow = 0
endif
if (ntru == 42 .and. nlev == 10) then
  gamma = 0.007
endif
rcrit(:) = max(0.85,max(sigma(:),1.-sigma(:)))
do im = 1, nugp
  rcritg(im,1:nlev) = rcrit(1:nlev)
end do
if (mypid == nroot) then
  open(unit=11,file=rainmod_namelist)
