  close(unit=11)
  write(unit=nud,fmt='(/," ***********************************************")')
  write(unit=nud,fmt='(" * RAINMOD ",a35," *")') trim(version)
  write(unit=nud,fmt='(" ***********************************************")')
  write(unit=nud,fmt='(" * Namelist RAINMOD_NL from <rainmod_namelist> *")')
  write(unit=nud,fmt='(" ***********************************************")')
  write(unit=nud,nml=rainmod_nl)
endif
call mpbci( kbeta )
call mpbci( nprl )
call mpbci( nprc )
