call mpbcr( clwcrit2 )
call mpbcr( pdeep )
call mpbcr( pdeepth )
call mpbcr( rkshallow )
call mpbcr( gamma )
call mpbcrn( rcrit,nlev )
call mpbcrn( rcrit,nlev )
call mpscgp( rcritg,rcritm,nlev )
if (clwcrit1 > clwcrit2) then
  clwfac = 1./(clwcrit1-clwcrit2)
else if (clwcrit1 < clwcrit2) then
  clwfac = -1.
else
  clwfac = 1.
endif
end subroutine rainini

